package com.runedefence;

import com.runedefence.model.Progression;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(RuneDefenceConfig.GROUP)
public interface RuneDefenceConfig extends Config
{
	String GROUP = "runedefence";
	String TUTORIAL_SEEN = "tutorialSeen";
	String XP_RATE = "xpRate";

	@ConfigItem(
		keyName = "autoStartWaves",
		name = "Auto-start waves",
		description = "Start the next wave by itself after the delay below. The first wave of a match is always started by hand.",
		position = 1
	)
	default boolean autoStartWaves()
	{
		return true;
	}

	@Range(min = 3, max = 120)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "interWaveDelay",
		name = "Delay between waves",
		description = "How long to wait before auto-starting the next wave",
		position = 2
	)
	default int interWaveDelay()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "pauseOnLogout",
		name = "Pause on logout",
		description = "Pause the match when you log out of OSRS, and resume when you log back in",
		position = 3
	)
	default boolean pauseOnLogout()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pauseOnHide",
		name = "Pause when panel hidden",
		description = "Pause the match while another sidebar panel is open",
		position = 4
	)
	default boolean pauseOnHide()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pauseOnFocusLost",
		name = "Pause when RuneLite loses focus",
		description = "Pause the match while you are using another window",
		position = 5
	)
	default boolean pauseOnFocusLost()
	{
		return false;
	}

	@ConfigItem(
		keyName = "battleEffects",
		name = "Battle effects",
		description = "Show hit numbers, blasts and death puffs. Turn off for a quieter game.",
		position = 6
	)
	default boolean battleEffects()
	{
		return true;
	}

	@ConfigItem(
		keyName = "unlockMessages",
		name = "Level-up messages",
		description = "Add a chat message when your RuneDefence level rises",
		position = 7
	)
	default boolean unlockMessages()
	{
		return true;
	}

	@Range(min = Progression.MIN_XP_RATE, max = Progression.MAX_XP_RATE)
	@ConfigItem(
		keyName = XP_RATE,
		name = "OSRS XP per RuneDefence XP",
		description = "How much OSRS XP earns 1 RuneDefence XP, from 1 (fastest levelling) to 10 (slowest). This also recalculates your current level from all the XP counted so far, and changing it never loses XP.",
		position = 8
	)
	default int xpRate()
	{
		return Progression.DEFAULT_XP_RATE;
	}
}

package com.runedefence;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.runedefence.client.XpProgressTracker;
import com.runedefence.content.ContentLoader;
import com.runedefence.engine.GameEngine;
import com.runedefence.model.Content;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.MatchSave;
import com.runedefence.model.Progression;
import com.runedefence.model.Records;
import com.runedefence.persistence.SaveRepository;
import com.runedefence.ui.RuneDefencePanel;
import com.runedefence.ui.SpriteAtlas;
import java.awt.BorderLayout;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.FocusChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "RuneDefence",
	description = "A tower defence minigame in the sidebar, levelled up by your OSRS XP",
	tags = {"game", "minigame", "tower", "defence", "td", "skilling"}
)
public class RuneDefencePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private RuneDefenceConfig config;

	@Inject
	private Gson gson;

	private final XpProgressTracker tracker = new XpProgressTracker();

	private NavigationButton navButton;
	private volatile RuneDefencePanel panel;
	private Content content;

	/** The account currently loaded, or null before the first login. */
	private volatile String profileKey;
	private volatile SaveRepository repository;
	/** Written on the client thread only; immutable, so other threads can read it safely. */
	private volatile Progression progress = new Progression(0, 0);

	@Override
	protected void startUp()
	{
		BufferedImage icon = ImageUtil.loadImageResource(RuneDefencePlugin.class, "/com/runedefence/panel_icon.png");
		PluginPanel view;
		try
		{
			content = ContentLoader.load(gson);
			SpriteAtlas atlas = new SpriteAtlas(gson);
			panel = new RuneDefencePanel(new GameEngine(content), atlas, new PanelHost());
			view = panel;
		}
		catch (IOException | RuntimeException e)
		{
			// Bad data must not take the client down with it, so explain in the sidebar instead.
			log.warn("RuneDefence could not load its game data", e);
			content = null;
			panel = null;
			view = new ErrorPanel();
		}

		navButton = NavigationButton.builder()
			.tooltip("RuneDefence")
			.icon(icon)
			.priority(8)
			.panel(view)
			.build();
		clientToolbar.addNavigation(navButton);

		if (panel == null)
		{
			return;
		}
		panel.applySettings(readSettings());
		tracker.reset();
		switchAccount(configManager.getRSProfileKey());
		if (!Boolean.TRUE.toString().equals(configManager.getConfiguration(RuneDefenceConfig.GROUP, RuneDefenceConfig.TUTORIAL_SEEN)))
		{
			panel.showTutorial();
		}
		log.info("RuneDefence started");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		if (panel != null)
		{
			SaveRepository repo = repository;
			if (repo != null)
			{
				repo.saveMatch(panel.currentSave());
			}
			panel.dispose();
			panel = null;
		}
		tracker.reset();
		repository = null;
		profileKey = null;
		progress = new Progression(0, 0);
		content = null;
		log.info("RuneDefence stopped");
	}

	// ---- OSRS events. These only observe, and never affect the game. --------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (panel == null)
		{
			return;
		}
		GameState state = event.getGameState();
		// Each of these is a session boundary: any XP change across one was not observed.
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			tracker.reset();
		}
		if (state == GameState.LOGIN_SCREEN && config.pauseOnLogout())
		{
			setPauseReason(RuneDefencePanel.PAUSE_LOGOUT, true);
		}
		else if (state == GameState.LOGGED_IN)
		{
			setPauseReason(RuneDefencePanel.PAUSE_LOGOUT, false);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (panel == null || tracker.isBaselined() || profileKey == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// Taken on a tick because the login stat burst has finished by then.
		Map<String, Integer> baseline = new HashMap<>();
		long total = 0;
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				int xp = client.getSkillExperience(skill);
				baseline.put(skill.name(), xp);
				total += xp;
			}
		}
		// All zeroes means stats haven't arrived. Baselining now would credit a whole account.
		if (total > 0)
		{
			tracker.baseline(baseline);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (panel == null || repository == null || event.getSkill() == Skill.OVERALL)
		{
			return;
		}
		int gain = tracker.observe(event.getSkill().name(), event.getXp());
		if (gain <= 0)
		{
			return;
		}
		Progression before = progress;
		Progression after = before.plus(gain);
		progress = after;
		repository.saveEligibleXp(after.eligibleOsrsXp);
		if (after.level() > before.level())
		{
			announceLevel(before.level(), after.level());
		}
		RuneDefencePanel target = panel;
		SwingUtilities.invokeLater(() -> target.setProgress(after));
	}

	private void announceLevel(int from, int to)
	{
		if (!config.unlockMessages())
		{
			return;
		}
		StringBuilder message = new StringBuilder("RuneDefence level ").append(to).append('!');
		for (DefenderDefinition d : content.defenders)
		{
			if (d.requiredLevel > from && d.requiredLevel <= to)
			{
				message.append(" Unlocked ").append(d.name).append('.');
			}
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message.toString(), null);
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		if (panel == null)
		{
			return;
		}
		// Never credit a difference between two characters.
		tracker.reset();
		String key = event.getNewProfile();
		// Logging out can clear the profile. Stay on the last account until there is a new one.
		if (key != null && !key.equals(profileKey))
		{
			switchAccount(key);
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		if (panel != null)
		{
			setPauseReason(RuneDefencePanel.PAUSE_FOCUS, config.pauseOnFocusLost() && !event.isFocused());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Saves share this group but carry a profile, and arrive on every XP drop.
		if (panel != null && RuneDefenceConfig.GROUP.equals(event.getGroup()) && event.getProfile() == null)
		{
			RuneDefencePanel.Settings settings = readSettings();
			RuneDefencePanel target = panel;
			SwingUtilities.invokeLater(() -> target.applySettings(settings));
			if (RuneDefenceConfig.XP_RATE.equals(event.getKey()))
			{
				clientThread.invoke(this::applyXpRate);
			}
		}
	}

	/** On the client thread because that's where progress is written. No chat message, as the player just did this. */
	private void applyXpRate()
	{
		RuneDefencePanel target = panel;
		if (target == null)
		{
			return;
		}
		Progression updated = progress.withXpRate(config.xpRate());
		progress = updated;
		SwingUtilities.invokeLater(() -> target.setProgress(updated));
	}

	private void setPauseReason(int reason, boolean on)
	{
		RuneDefencePanel target = panel;
		SwingUtilities.invokeLater(() -> target.setPauseReason(reason, on));
	}

	// ---- Accounts and saves -------------------------------------------------

	/** Loads an account's data. With no key, this session's progress is simply not kept. */
	private void switchAccount(String key)
	{
		SaveRepository previous = repository;
		boolean wasGuest = previous != null && profileKey == null;
		SaveRepository next = new SaveRepository(key == null ? new MemoryStore() : new ProfileStore(key), gson);
		repository = next;
		profileKey = key;
		Progression loaded = new Progression(next.loadEligibleXp(), 0, config.xpRate());
		progress = loaded;
		RuneDefencePanel target = panel;
		Runnable swap = () ->
		{
			if (previous != null)
			{
				previous.saveMatch(target.currentSave());
			}
			MatchSave saved = next.loadMatch();
			// A match started before logging in carries over, unless this account has its own.
			target.loadAccount(loaded, next.loadRecords(), saved, wasGuest && saved == null);
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			swap.run();
		}
		else
		{
			SwingUtilities.invokeLater(swap);
		}
	}

	private RuneDefencePanel.Settings readSettings()
	{
		RuneDefencePanel.Settings s = new RuneDefencePanel.Settings();
		s.autoStart = config.autoStartWaves();
		s.interWaveDelaySeconds = config.interWaveDelay();
		s.pauseOnHide = config.pauseOnHide();
		s.effects = config.battleEffects();
		return s;
	}

	@Provides
	RuneDefenceConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(RuneDefenceConfig.class);
	}

	private final class PanelHost implements RuneDefencePanel.Host
	{
		@Override
		public void saveMatch(MatchSave save)
		{
			SaveRepository repo = repository;
			if (repo != null)
			{
				repo.saveMatch(save);
			}
		}

		@Override
		public void saveRecords(Records records)
		{
			SaveRepository repo = repository;
			if (repo != null)
			{
				repo.saveRecords(records);
			}
		}

		@Override
		public void tutorialFinished()
		{
			configManager.setConfiguration(RuneDefenceConfig.GROUP, RuneDefenceConfig.TUTORIAL_SEEN, true);
		}
	}

	/** Saves against one RuneLite profile, which is what keeps characters apart. */
	private final class ProfileStore implements SaveRepository.Store
	{
		private final String key;

		ProfileStore(String key)
		{
			this.key = key;
		}

		@Override
		public String get(String name)
		{
			return configManager.getConfiguration(RuneDefenceConfig.GROUP, key, name);
		}

		@Override
		public void set(String name, String value)
		{
			configManager.setConfiguration(RuneDefenceConfig.GROUP, key, name, value);
		}

		@Override
		public void unset(String name)
		{
			configManager.unsetConfiguration(RuneDefenceConfig.GROUP, key, name);
		}
	}

	/** For playing before the first login of a client run, when there's no profile yet. */
	private static final class MemoryStore implements SaveRepository.Store
	{
		private final Map<String, String> values = new HashMap<>();

		@Override
		public String get(String name)
		{
			return values.get(name);
		}

		@Override
		public void set(String name, String value)
		{
			values.put(name, value);
		}

		@Override
		public void unset(String name)
		{
			values.remove(name);
		}
	}

	private static final class ErrorPanel extends PluginPanel
	{
		ErrorPanel()
		{
			setLayout(new BorderLayout());
			add(new JLabel("<html>RuneDefence could not load its game data. Try reinstalling the plugin.</html>"), BorderLayout.NORTH);
		}
	}
}

package com.runedefence.client;

import java.util.HashMap;
import java.util.Map;

/**
 * Decides how much of each observed XP change counts as earned. Only gains seen
 * since the session baseline count, so existing XP and anything gained while the
 * plugin wasn't watching are never credited.
 *
 * Skills are plain strings so that this can be tested without a client.
 */
public final class XpProgressTracker
{
	/** Larger than any single legitimate XP drop. Anything above it is treated as bad data. */
	static final int MAX_PLAUSIBLE_GAIN = 2_000_000;

	private final Map<String, Integer> lastObserved = new HashMap<>();
	private boolean baselined;

	/** Starts a new session: nothing counts until {@link #baseline} is next called. */
	public void reset()
	{
		lastObserved.clear();
		baselined = false;
	}

	public boolean isBaselined()
	{
		return baselined;
	}

	public void baseline(Map<String, Integer> skillXp)
	{
		lastObserved.clear();
		lastObserved.putAll(skillXp);
		baselined = true;
	}

	/** Returns the XP to credit for this observation, or 0. */
	public int observe(String skill, int xp)
	{
		if (!baselined)
		{
			return 0;
		}
		Integer last = lastObserved.put(skill, xp);
		if (last == null)
		{
			return 0;
		}
		int gain = xp - last;
		// Zero is a repeat or a boost change. Negative is a rollback: rebaselined, nothing is taken away.
		return gain > 0 && gain <= MAX_PLAUSIBLE_GAIN ? gain : 0;
	}
}

package com.runedefence.content;

import com.google.gson.Gson;
import com.runedefence.model.Content;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;

public final class ContentLoader
{
	private static final String RESOURCE = "/com/runedefence/content.json";

	private ContentLoader()
	{
	}

	/** Loads and validates the game data. Throws a descriptive exception if it is unusable. */
	public static Content load(Gson gson) throws IOException
	{
		try (InputStream in = ContentLoader.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Content content = gson.fromJson(reader, Content.class);
				ContentValidator.validate(content);
				return content;
			}
		}
	}
}

package com.runedefence.content;

import com.runedefence.model.Content;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.EnemyDefinition;
import com.runedefence.model.MapDefinition;
import com.runedefence.model.UpgradeDefinition;
import com.runedefence.model.WaveDefinition;
import java.util.HashSet;
import java.util.Set;

/** Rejects bad game data at startup, so that it can't surface as a crash mid-match. */
public final class ContentValidator
{
	private ContentValidator()
	{
	}

	public static void validate(Content c)
	{
		check(c != null && c.version != null, "content has no version");
		check(c.defenders != null && c.defenders.length > 0, "no defenders");
		check(c.enemies != null && c.enemies.length > 0, "no enemies");
		check(c.maps != null && c.maps.length > 0, "no maps");

		Set<String> ids = new HashSet<>();
		for (DefenderDefinition d : c.defenders)
		{
			check(d.id != null && ids.add(d.id), "duplicate defender id " + d.id);
			check(d.requiredLevel >= 1 && d.requiredLevel <= 99, d.id + ": illegal required level");
			check(d.cost > 0, d.id + ": cost must be positive");
			check(d.size >= 1 && d.size <= 3, d.id + ": size must be 1 to 3");
			check(fraction(d.critChance) && fraction(d.rootChance) && fraction(d.slowPercent), d.id + ": bad chance");
			check(d.burnDps >= 0 && d.splash >= 0 && d.armourPierce >= 0, d.id + ": bad effect");
			check(positive(d.rangeTiles) && positive(d.attacksPerSecond), d.id + ": bad range or attack speed");
			check(d.damage > 0, d.id + ": damage must be positive");
			check(d.rootChance == 0 || positive(d.rootSeconds), d.id + ": a bind needs a duration");
			check(d.damageType != null && d.targeting != null, d.id + ": missing damage type or targeting");
			boolean ranged = d.projectile != null && !d.projectile.isEmpty();
			check(!ranged || positive(d.projectileSpeed), d.id + ": projectile needs a speed");
			checkPath(d, d.pathA);
			checkPath(d, d.pathB);
		}

		ids.clear();
		for (EnemyDefinition e : c.enemies)
		{
			check(e.id != null && ids.add(e.id), "duplicate enemy id " + e.id);
			check(e.maxHealth > 0 && positive(e.speed), e.id + ": bad health or speed");
			check(e.goldReward >= 0 && e.baseDamage > 0 && e.armour >= 0, e.id + ": bad reward, damage or armour");
			check(fraction(e.magicResist) && fraction(e.evasion), e.id + ": resist and evasion must be 0 to 1");
			check(e.splitCount <= 0 || c.enemy(e.splitInto) != null, e.id + ": splits into an unknown enemy");
			check(e.gazeRange <= 0 || positive(e.gazeEverySeconds) && positive(e.gazeSeconds), e.id + ": bad gaze");
		}

		ids.clear();
		for (MapDefinition m : c.maps)
		{
			check(m.id != null && ids.add(m.id), "duplicate map id " + m.id);
			checkMap(c, m);
		}
	}

	private static void checkPath(DefenderDefinition d, UpgradeDefinition[] path)
	{
		check(path != null && path.length == DefenderDefinition.TIERS, d.id + ": each path needs two tiers");
		for (UpgradeDefinition u : path)
		{
			check(u.cost > 0 && u.name != null, d.id + ": bad upgrade " + u.id);
			check(u.rootChance == 0 || positive(d.rootSeconds) || positive(u.rootSeconds), d.id + ": " + u.id + " binds with no duration");
		}
	}

	private static void checkMap(Content c, MapDefinition m)
	{
		check(m.columns > 0 && m.rows > 0 && m.tiles != null && m.tiles.length == m.rows, m.id + ": bad grid");
		for (String row : m.tiles)
		{
			check(row.length() == m.columns, m.id + ": bad row width");
		}
		check(m.requiredLevel >= 1 && m.requiredLevel <= 99, m.id + ": illegal required level");
		check(m.startingGold > 0 && m.startingHealth > 0, m.id + ": bad starting gold or health");
		check(positive(m.enemySpeed) && positive(m.enemyHealth) && positive(m.defenderSpeed) && positive(m.goldMultiplier),
			m.id + ": bad map rules");
		check(m.rotateLanesEvery >= 0 && m.deathHealRadius >= 0 && fraction(m.deathHealPercent), m.id + ": bad map rules");
		check(m.paths != null && m.paths.length > 0, m.id + ": no lanes");
		int[] goal = null;
		for (int[][] lane : m.paths)
		{
			checkLane(m, lane);
			int[] end = lane[lane.length - 1];
			// Lanes may start anywhere, but they all have to finish at the same keep.
			check(goal == null || (goal[0] == end[0] && goal[1] == end[1]), m.id + ": lanes must end together");
			goal = end;
		}
		check(m.waves != null && m.waves.length > 0, m.id + ": no waves");
		for (int milestone : m.milestones)
		{
			check(milestone > 0 && milestone <= m.waves.length, m.id + ": milestone beyond the last wave");
		}
		for (int w = 0; w < m.waves.length; w++)
		{
			WaveDefinition wave = m.waves[w];
			check(wave.groups != null && wave.groups.length > 0, m.id + ": empty wave " + (w + 1));
			for (WaveDefinition.Group g : wave.groups)
			{
				check(c.enemy(g.enemy) != null, m.id + ": unknown enemy " + g.enemy);
				check(fields(m, g.enemy), m.id + ": wave " + (w + 1) + " uses " + g.enemy + ", which isn't on its list");
				String child = c.enemy(g.enemy).splitInto;
				check(child == null || fields(m, child), m.id + ": " + g.enemy + " splits into " + child + ", which isn't on its list");
				check(g.count > 0 && g.intervalMs >= 0 && g.delayMs >= 0 && positive(g.health),
					m.id + ": bad group in wave " + (w + 1));
			}
		}
	}

	private static boolean fields(MapDefinition m, String enemy)
	{
		for (String id : m.monsters)
		{
			if (id.equals(enemy))
			{
				return true;
			}
		}
		return false;
	}

	private static void checkLane(MapDefinition m, int[][] lane)
	{
		check(lane != null && lane.length >= 2, m.id + ": lane too short");
		for (int i = 0; i < lane.length; i++)
		{
			int[] p = lane[i];
			check(p.length == 2, m.id + ": bad waypoint");
			check(p[0] >= -1 && p[1] >= -1 && p[0] <= m.columns && p[1] <= m.rows, m.id + ": waypoint off the map");
			if (i > 0)
			{
				int[] q = lane[i - 1];
				check((p[0] == q[0]) != (p[1] == q[1]), m.id + ": lane must move in straight, connected lines");
			}
		}
	}

	private static boolean positive(double v)
	{
		return v > 0 && !Double.isInfinite(v);
	}

	private static boolean fraction(double v)
	{
		return v >= 0 && v <= 1;
	}

	private static void check(boolean ok, String message)
	{
		if (!ok)
		{
			throw new IllegalArgumentException("Invalid game data: " + message);
		}
	}
}

package com.runedefence.engine;

import com.runedefence.model.DamageType;
import com.runedefence.model.TargetingMode;
import java.util.List;

/** Targeting and damage rules. Every point of damage is calculated in {@link #damageFor}. */
final class CombatSystem
{
	private CombatSystem()
	{
	}

	static EnemyInstance select(DefenderInstance d, List<EnemyInstance> enemies)
	{
		EnemyInstance best = null;
		double bestScore = 0;
		boolean bestWanted = false;
		double rangeSq = d.range * d.range;
		TargetingMode mode = d.targeting;
		for (int i = 0, n = enemies.size(); i < n; i++)
		{
			EnemyInstance e = enemies.get(i);
			if (e.dead)
			{
				continue;
			}
			double dx = e.x - d.x;
			double dy = e.y - d.y;
			double distSq = dx * dx + dy * dy;
			if (distSq > rangeSq)
			{
				continue;
			}
			double score;
			switch (mode)
			{
				case LAST:
					score = e.distanceLeft();
					break;
				case STRONGEST:
					score = e.hp;
					break;
				case WEAKEST:
					score = -e.hp;
					break;
				case CLOSEST:
					score = -distSq;
					break;
				case FIRST:
				default:
					score = -e.distanceLeft();
					break;
			}
			// A binder spreads out rather than re-hitting what it can't hold, but never holds fire.
			boolean wanted = !d.def.seeksUnbound || e.canBeBound();
			if (best == null || (wanted && !bestWanted) || (wanted == bestWanted && score > bestScore))
			{
				best = e;
				bestScore = score;
				bestWanted = wanted;
			}
		}
		return best;
	}

	/** Armour is a flat reduction to physical hits; magic resist is a share of magic hits. */
	static int damageFor(int raw, DamageType type, EnemyInstance e, int armourPierce)
	{
		double damage = raw;
		if (type == DamageType.PHYSICAL)
		{
			damage -= e.effectiveArmour(armourPierce);
		}
		else
		{
			damage *= 1 - e.magicResist;
		}
		return Math.max(1, (int) Math.round(damage));
	}
}

package com.runedefence.engine;

import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.Effects;
import com.runedefence.model.TargetingMode;
import com.runedefence.model.UpgradeDefinition;

/** A placed defender and its stats, recalculated whenever it is upgraded. */
public final class DefenderInstance
{
	public final DefenderDefinition def;
	/** Top left tile of its footprint. */
	public final int col;
	public final int row;
	/** Centre of its footprint, which is where range is measured from. */
	public final double x;
	public final double y;

	public int tierA;
	public int tierB;
	public int invested;
	public TargetingMode targeting;

	public int damage;
	public double range;
	public double attacksPerSecond;
	public Effects stats;

	/** The best aura from a neighbour, recalculated when the board changes. */
	public double auraDamage;
	public double auraSpeed;

	double cooldown;
	int attackCount;
	/** Petrified and unable to attack while above zero. */
	public double stunTimer;

	/** Render hints: time left in the attack animation, and which way to face. */
	public double attackAnim;
	public boolean facingLeft;

	DefenderInstance(DefenderDefinition def, int col, int row)
	{
		this.def = def;
		this.col = col;
		this.row = row;
		this.x = col + def.size / 2.0;
		this.y = row + def.size / 2.0;
		this.targeting = def.targeting;
		recalculate();
	}

	/** What a defender at these tiers would be, using the same rules as one on the board. */
	public static DefenderInstance preview(DefenderDefinition def, int tierA, int tierB)
	{
		DefenderInstance d = new DefenderInstance(def, 0, 0);
		d.tierA = tierA;
		d.tierB = tierB;
		d.recalculate();
		return d;
	}

	public int tier(int path)
	{
		return path == 0 ? tierA : tierB;
	}

	public boolean occupies(int c, int r)
	{
		return c >= col && r >= row && c < col + def.size && r < row + def.size;
	}

	public int effectiveDamage()
	{
		return (int) Math.round(damage * (1 + auraDamage));
	}

	public double effectiveAttacksPerSecond()
	{
		return attacksPerSecond * (1 + auraSpeed);
	}

	public void recalculate()
	{
		damage = def.damage;
		range = def.rangeTiles;
		attacksPerSecond = def.attacksPerSecond;
		stats = new Effects();
		stats.add(def);
		for (int path = 0; path < 2; path++)
		{
			UpgradeDefinition[] upgrades = def.path(path);
			for (int i = 0; i < tier(path); i++)
			{
				UpgradeDefinition u = upgrades[i];
				damage += u.damage;
				range += u.range;
				if (u.attackSpeedMultiplier > 0)
				{
					attacksPerSecond *= u.attackSpeedMultiplier;
				}
				stats.add(u);
			}
		}
	}
}

package com.runedefence.engine;

import com.runedefence.model.EnemyDefinition;

public final class EnemyInstance
{
	public final EnemyDefinition def;
	public final double maxHp;
	public double hp;

	/** Distance travelled along the path, in tiles. */
	public double progress;
	public double x;
	public double y;
	public double prevX;
	public double prevY;

	/** A small sideways offset that stops a group walking in a single-file line. Visual only. */
	public final double laneOffset;
	/** The lane it walks. */
	final PathTable path;
	/** Its own resistance plus whatever the map adds. */
	final double magicResist;
	/** Render hints: time left on the hit flash, and which way it last walked. */
	public double hitAnim;
	public boolean facingLeft;

	int armourBroken;
	double armourBreakTimer;
	double burnDps;
	double burnTimer;
	double slowPercent;
	double slowTimer;
	double rootTimer;
	/** Can't be bound again until this runs out. */
	double bindLockout;
	double weakenPercent;
	double weakenTimer;
	double gazeTimer;
	boolean dead;

	EnemyInstance(EnemyDefinition def, double maxHp, double laneOffset)
	{
		this(def, maxHp, laneOffset, null, def.magicResist);
	}

	EnemyInstance(EnemyDefinition def, double maxHp, double laneOffset, PathTable path, double magicResist)
	{
		this.def = def;
		this.maxHp = maxHp;
		this.hp = maxHp;
		this.laneOffset = laneOffset;
		this.path = path;
		this.magicResist = magicResist;
	}

	/** Tiles left to walk, which compares fairly across lanes of different lengths. */
	double distanceLeft()
	{
		return (path != null ? path.length : 0) - progress;
	}

	public boolean isArmourBroken()
	{
		return armourBroken > 0;
	}

	public boolean isBurning()
	{
		return burnTimer > 0;
	}

	public boolean isSlowed()
	{
		return slowTimer > 0;
	}

	public boolean isRooted()
	{
		return rootTimer > 0;
	}

	boolean canBeBound()
	{
		return !def.boss && rootTimer <= 0 && bindLockout <= 0;
	}

	public boolean isWeakened()
	{
		return weakenTimer > 0;
	}

	public int effectiveArmour(int pierce)
	{
		return Math.max(0, def.armour - armourBroken - pierce);
	}
}

package com.runedefence.engine;

/** A visual cue the renderer picks up. It has no effect on the simulation. */
public final class FxEvent
{
	public enum Kind
	{
		HIT,
		CRIT,
		MISS,
		BLAST,
		DEATH,
		LEAK,
		GAZE
	}

	public Kind kind;
	public double x;
	public double y;
	public int value;
	/** Burst sprite and radius in tiles, for a blast. */
	public String sprite;
	public double radius;
}

package com.runedefence.engine;

import com.runedefence.model.Content;
import com.runedefence.model.DamageType;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.Effects;
import com.runedefence.model.EnemyDefinition;
import com.runedefence.model.MapDefinition;
import com.runedefence.model.MatchSave;
import com.runedefence.model.UpgradeDefinition;
import com.runedefence.model.WaveDefinition;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * The whole game simulation, with no RuneLite or Swing dependencies. It is not
 * thread-safe and is owned by one thread (the Swing EDT in the plugin), which
 * both steps and paints it, so nothing can be mutated while it is being drawn.
 *
 * Given the same seed, content and commands, a match always plays out the same.
 */
public final class GameEngine
{
	public static final double STEP_SECONDS = 0.05;
	public static final int RESALE_PERCENT = 70;

	private static final double ATTACK_ANIM_SECONDS = 0.25;
	private static final double HIT_ANIM_SECONDS = 0.1;
	public static final double ARMOUR_BREAK_SECONDS = 4;
	public static final double DEFAULT_CRIT_MULTIPLIER = 2;
	/**
	 * Measured from the moment a bind lands, as a multiple of how long it holds. At 2, an
	 * enemy walks for at least as long as it was held, so it can't be frozen more than
	 * half the time, however many binders cover it.
	 */
	private static final double BIND_LOCKOUT_RATIO = 2;
	private static final int FX_CAPACITY = 64;
	private static final int MAX_PROJECTILES = 200;
	private static final double MAX_SLOW = 0.8;
	private static final double MAX_RESIST = 0.9;
	private static final double SPLIT_SPACING = 0.25;

	public enum State
	{
		MENU,
		PREPARING,
		RUNNING,
		PAUSED,
		WAVE_COMPLETE,
		VICTORY,
		DEFEAT
	}

	public enum Result
	{
		OK,
		WRONG_STATE,
		LOCKED,
		NOT_ENOUGH_GOLD,
		INVALID_TILE,
		NOT_FOUND,
		PATH_MAXED,
		PATH_BLOCKED
	}

	public interface MatchEndListener
	{
		void onMatchEnd(GameEngine engine, boolean victory);
	}

	private final Content content;
	private final List<DefenderInstance> defenders = new ArrayList<>();
	private final List<EnemyInstance> enemies = new ArrayList<>();
	private final List<Projectile> projectiles = new ArrayList<>();
	/** Killed this step and due to burst, which waits so that a blast can't hit what it just created. */
	private final List<EnemyInstance> splitting = new ArrayList<>();

	private final FxEvent[] fx = new FxEvent[FX_CAPACITY];
	private int fxHead;
	private int fxSize;

	private State state = State.MENU;
	private State resumeState = State.MENU;
	private MapDefinition map;
	private PathTable[] lanes;
	private Random rng = new Random(0);
	private long seed;

	private int playerLevel = 1;
	private double autoStartDelay;
	private double autoStartTimer;

	private int gold;
	private int baseHealth;
	private int waveIndex;
	private int goldSpent;
	private int enemiesDefeated;
	private long ticks;

	private double waveTime;
	private int[] spawned = new int[0];
	private MatchEndListener matchEndListener;
	private MatchSave checkpoint;

	public GameEngine(Content content)
	{
		this.content = content;
	}

	// ---- Match lifecycle ----------------------------------------------------

	public Result newMatch(String mapId, long matchSeed)
	{
		MapDefinition m = content.map(mapId);
		if (m == null)
		{
			return Result.NOT_FOUND;
		}
		if (playerLevel < m.requiredLevel)
		{
			return Result.LOCKED;
		}
		loadMap(m, matchSeed);
		gold = m.startingGold;
		baseHealth = m.startingHealth;
		waveIndex = 0;
		goldSpent = 0;
		enemiesDefeated = 0;
		ticks = 0;
		state = State.PREPARING;
		checkpoint = null;
		return Result.OK;
	}

	private void loadMap(MapDefinition m, long matchSeed)
	{
		map = m;
		lanes = new PathTable[m.paths.length];
		for (int i = 0; i < lanes.length; i++)
		{
			lanes[i] = new PathTable(m.paths[i]);
		}
		seed = matchSeed;
		rng = new Random(matchSeed);
		clearField();
		defenders.clear();
	}

	private void clearField()
	{
		enemies.clear();
		projectiles.clear();
		splitting.clear();
		fxSize = 0;
		waveTime = 0;
	}

	/** Leaves the match without recording it. Permanent progression is never affected. */
	public void abandon()
	{
		clearField();
		defenders.clear();
		map = null;
		lanes = null;
		checkpoint = null;
		state = State.MENU;
	}

	public Result startWave()
	{
		if (state != State.PREPARING && state != State.WAVE_COMPLETE)
		{
			return Result.WRONG_STATE;
		}
		checkpoint = buildCheckpoint();
		beginWave();
		return Result.OK;
	}

	private void beginWave()
	{
		clearField();
		spawned = new int[currentWave().groups.length];
		// Reseeding per wave lets a checkpoint resume with an identical random sequence.
		rng = new Random(seed * 31 + waveIndex);
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			d.cooldown = 0;
			d.attackCount = 0;
			d.attackAnim = 0;
			d.stunTimer = 0;
		}
		state = State.RUNNING;
	}

	public Result pause()
	{
		if (state != State.RUNNING && state != State.PREPARING && state != State.WAVE_COMPLETE)
		{
			return Result.WRONG_STATE;
		}
		resumeState = state;
		state = State.PAUSED;
		return Result.OK;
	}

	public Result resume()
	{
		if (state != State.PAUSED)
		{
			return Result.WRONG_STATE;
		}
		state = resumeState;
		return Result.OK;
	}

	public boolean isMatchActive()
	{
		return state != State.MENU && state != State.VICTORY && state != State.DEFEAT;
	}

	// ---- Economy commands ---------------------------------------------------

	/** Can this defender be placed at all, regardless of where? */
	public Result canPurchase(DefenderDefinition def)
	{
		if (!isMatchActive())
		{
			return Result.WRONG_STATE;
		}
		if (playerLevel < def.requiredLevel)
		{
			return Result.LOCKED;
		}
		return gold < def.cost ? Result.NOT_ENOUGH_GOLD : Result.OK;
	}

	public boolean isTileFree(int col, int row)
	{
		return canPlaceAt(1, col, row);
	}

	/** Is a square of this size clear of scenery, path and other defenders? */
	public boolean canPlaceAt(int size, int col, int row)
	{
		if (map == null || !map.canFit(col, row, size))
		{
			return false;
		}
		for (int r = row; r < row + size; r++)
		{
			for (int c = col; c < col + size; c++)
			{
				if (defenderAt(c, r) != null)
				{
					return false;
				}
			}
		}
		return true;
	}

	public Result place(String defenderId, int col, int row)
	{
		DefenderDefinition def = content.defender(defenderId);
		if (def == null)
		{
			return Result.NOT_FOUND;
		}
		Result allowed = canPurchase(def);
		if (allowed != Result.OK)
		{
			return allowed;
		}
		if (!canPlaceAt(def.size, col, row))
		{
			return Result.INVALID_TILE;
		}
		DefenderInstance d = new DefenderInstance(def, col, row);
		d.invested = def.cost;
		spend(def.cost);
		defenders.add(d);
		recalculateAuras();
		return Result.OK;
	}

	/** The next upgrade on a path, or null if the path is complete. */
	public static UpgradeDefinition nextUpgrade(DefenderInstance d, int pathIndex)
	{
		UpgradeDefinition[] upgrades = d.def.path(pathIndex);
		int tier = d.tier(pathIndex);
		return tier < upgrades.length ? upgrades[tier] : null;
	}

	/** Paths are exclusive past tier one: only one of them can reach tier two. */
	public static boolean isPathBlocked(DefenderInstance d, int pathIndex)
	{
		return d.tier(pathIndex) >= 1 && d.tier(1 - pathIndex) >= 2;
	}

	public Result upgrade(DefenderInstance d, int pathIndex)
	{
		if (!isMatchActive())
		{
			return Result.WRONG_STATE;
		}
		if (!defenders.contains(d))
		{
			return Result.NOT_FOUND;
		}
		UpgradeDefinition next = nextUpgrade(d, pathIndex);
		if (next == null)
		{
			return Result.PATH_MAXED;
		}
		if (isPathBlocked(d, pathIndex))
		{
			return Result.PATH_BLOCKED;
		}
		if (gold < next.cost)
		{
			return Result.NOT_ENOUGH_GOLD;
		}
		spend(next.cost);
		d.invested += next.cost;
		if (pathIndex == 0)
		{
			d.tierA++;
		}
		else
		{
			d.tierB++;
		}
		d.recalculate();
		recalculateAuras();
		return Result.OK;
	}

	public static int sellValue(DefenderInstance d)
	{
		// Whole numbers only: as a double, 90 * 0.7 is 62.99999 and would short-change a sale.
		return d.invested * RESALE_PERCENT / 100;
	}

	public Result sell(DefenderInstance d)
	{
		if (!isMatchActive())
		{
			return Result.WRONG_STATE;
		}
		if (!defenders.remove(d))
		{
			return Result.NOT_FOUND;
		}
		gold += sellValue(d);
		recalculateAuras();
		return Result.OK;
	}

	public void cycleTargeting(DefenderInstance d)
	{
		d.targeting = d.targeting.next();
	}

	/** Each defender gets the single strongest aura of each kind in reach, so they never stack. */
	private void recalculateAuras()
	{
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			d.auraDamage = 0;
			d.auraSpeed = 0;
			for (int j = 0; j < defenders.size(); j++)
			{
				DefenderInstance a = defenders.get(j);
				if (a != d && a.stats.auraRadius > 0 && Math.hypot(a.x - d.x, a.y - d.y) <= a.stats.auraRadius)
				{
					d.auraDamage = Math.max(d.auraDamage, a.stats.auraDamagePercent);
					d.auraSpeed = Math.max(d.auraSpeed, a.stats.auraSpeedPercent);
				}
			}
		}
	}

	/** Package-private on purpose: nothing in the plugin can create gold from nowhere. */
	void addGold(int amount)
	{
		gold += amount;
	}

	private void spend(int amount)
	{
		gold -= amount;
		goldSpent += amount;
	}

	public DefenderInstance defenderAt(int col, int row)
	{
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			if (d.occupies(col, row))
			{
				return d;
			}
		}
		return null;
	}

	// ---- Simulation ---------------------------------------------------------

	/** Advances the game by one fixed {@link #STEP_SECONDS} step. */
	public void step()
	{
		if (state == State.WAVE_COMPLETE)
		{
			if (autoStartDelay > 0)
			{
				autoStartTimer -= STEP_SECONDS;
				if (autoStartTimer <= 0)
				{
					startWave();
				}
			}
			animateDefenders();
			return;
		}
		if (state != State.RUNNING)
		{
			return;
		}
		ticks++;
		waveTime += STEP_SECONDS;
		spawnEnemies();
		moveEnemies();
		if (state != State.RUNNING)
		{
			// The keep fell. Nothing else may happen, so the recorded result stays final.
			return;
		}
		attack();
		moveProjectiles();
		removeDeadEnemies();
		spawnSplits();
		if (state == State.RUNNING && isWaveFinished())
		{
			finishWave();
		}
	}

	private void spawnEnemies()
	{
		WaveDefinition.Group[] groups = currentWave().groups;
		for (int i = 0; i < groups.length; i++)
		{
			WaveDefinition.Group g = groups[i];
			while (spawned[i] < g.count && waveTime * 1000 >= g.delayMs + spawned[i] * (double) g.intervalMs)
			{
				spawn(content.enemy(g.enemy), g.health * map.enemyHealth, laneFor(spawned[i]), 0);
				spawned[i]++;
			}
		}
	}

	/** Either the one open lane, or groups taking turns between lanes so that none can be ignored. */
	private PathTable laneFor(int spawnedSoFar)
	{
		return lanes[map.rotateLanesEvery > 0 ? activeLane() : spawnedSoFar % lanes.length];
	}

	/** The lane open for the current or next wave, on a map where the route shifts. */
	public int activeLane()
	{
		return map.rotateLanesEvery > 0 ? (waveIndex / map.rotateLanesEvery) % lanes.length : -1;
	}

	private void spawn(EnemyDefinition def, double healthMultiplier, PathTable lane, double progress)
	{
		double resist = Math.min(MAX_RESIST, def.magicResist + map.extraMagicResist);
		EnemyInstance e = new EnemyInstance(def, def.maxHealth * healthMultiplier, (rng.nextDouble() - 0.5) * 0.3, lane, resist);
		e.progress = progress;
		lane.locate(progress, e);
		e.prevX = e.x;
		e.prevY = e.y;
		enemies.add(e);
	}

	private void spawnSplits()
	{
		for (int i = 0; i < splitting.size(); i++)
		{
			EnemyInstance parent = splitting.get(i);
			EnemyDefinition child = content.enemy(parent.def.splitInto);
			// Children keep the parent's wave scaling, and fan out a little along the path.
			double multiplier = parent.maxHp / parent.def.maxHealth;
			for (int n = 0; n < parent.def.splitCount; n++)
			{
				double offset = (n - (parent.def.splitCount - 1) / 2.0) * SPLIT_SPACING;
				spawn(child, multiplier, parent.path, Math.max(0, Math.min(parent.path.length - 0.01, parent.progress + offset)));
			}
		}
		splitting.clear();
	}

	private void moveEnemies()
	{
		for (int i = 0; i < enemies.size() && state == State.RUNNING; i++)
		{
			EnemyInstance e = enemies.get(i);
			e.prevX = e.x;
			e.prevY = e.y;
			if (e.hitAnim > 0)
			{
				e.hitAnim -= STEP_SECONDS;
			}
			updateStatuses(e);
			if (e.dead)
			{
				continue;
			}
			if (e.def.gazeRange > 0)
			{
				gaze(e);
			}
			if (e.rootTimer <= 0)
			{
				double slow = e.slowTimer > 0 ? e.slowPercent : 0;
				e.progress += e.def.speed * map.enemySpeed * (1 - slow) * STEP_SECONDS;
			}
			if (e.progress >= e.path.length)
			{
				escape(e);
			}
			else
			{
				e.path.locate(e.progress, e);
				if (e.x != e.prevX)
				{
					e.facingLeft = e.x < e.prevX;
				}
			}
		}
	}

	private void updateStatuses(EnemyInstance e)
	{
		if (e.armourBreakTimer > 0)
		{
			e.armourBreakTimer -= STEP_SECONDS;
			if (e.armourBreakTimer <= 0)
			{
				e.armourBroken = 0;
			}
		}
		e.slowTimer -= STEP_SECONDS;
		e.rootTimer -= STEP_SECONDS;
		e.bindLockout -= STEP_SECONDS;
		e.weakenTimer -= STEP_SECONDS;
		if (e.def.regenPerSecond > 0 && e.hp < e.maxHp)
		{
			e.hp = Math.min(e.maxHp, e.hp + e.def.regenPerSecond * STEP_SECONDS);
		}
		if (e.burnTimer > 0)
		{
			e.burnTimer -= STEP_SECONDS;
			damage(e, e.burnDps * STEP_SECONDS);
		}
	}

	private void gaze(EnemyInstance e)
	{
		e.gazeTimer -= STEP_SECONDS;
		if (e.gazeTimer > 0)
		{
			return;
		}
		DefenderInstance victim = null;
		double best = e.def.gazeRange * e.def.gazeRange;
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			double dx = d.x - e.x;
			double dy = d.y - e.y;
			double distSq = dx * dx + dy * dy;
			if (distSq <= best)
			{
				best = distSq;
				victim = d;
			}
		}
		if (victim != null)
		{
			victim.stunTimer = Math.max(victim.stunTimer, e.def.gazeSeconds);
			e.gazeTimer = e.def.gazeEverySeconds;
			emit(FxEvent.Kind.GAZE, victim.x, victim.y, 0);
		}
	}

	private void escape(EnemyInstance e)
	{
		e.dead = true;
		baseHealth = Math.max(0, baseHealth - e.def.baseDamage);
		emit(FxEvent.Kind.LEAK, e.x, e.y, e.def.baseDamage);
		if (baseHealth == 0)
		{
			endMatch(false);
		}
	}

	private void attack()
	{
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			animate(d);
			if (d.stunTimer > 0)
			{
				d.stunTimer -= STEP_SECONDS;
				continue;
			}
			d.cooldown -= STEP_SECONDS;
			if (d.cooldown > 0)
			{
				continue;
			}
			EnemyInstance target = CombatSystem.select(d, enemies);
			if (target == null)
			{
				d.cooldown = 0;
				continue;
			}
			fire(d, target);
			d.cooldown += attackInterval(d);
		}
	}

	/** Real seconds between this defender's attacks, on this map, with any aura. Lower is faster. */
	public double attackInterval(DefenderInstance d)
	{
		return 1 / (d.effectiveAttacksPerSecond() * map.defenderSpeed);
	}

	private void animateDefenders()
	{
		for (int i = 0; i < defenders.size(); i++)
		{
			animate(defenders.get(i));
		}
	}

	private static void animate(DefenderInstance d)
	{
		if (d.attackAnim > 0)
		{
			d.attackAnim -= STEP_SECONDS;
		}
	}

	private void fire(DefenderInstance d, EnemyInstance target)
	{
		d.attackAnim = ATTACK_ANIM_SECONDS;
		d.facingLeft = target.x < d.x;
		d.attackCount++;
		int strikes = d.stats.strikeEvery > 0 && d.attackCount % d.stats.strikeEvery == 0 ? 2 : 1;
		DamageType type = d.def.damageType;
		if (d.def.alternatesDamage && d.attackCount % 2 == 0)
		{
			type = type == DamageType.MAGIC ? DamageType.PHYSICAL : DamageType.MAGIC;
		}

		if (d.def.projectile == null || d.def.projectile.isEmpty() || projectiles.size() >= MAX_PROJECTILES)
		{
			impact(d, type, strikes, target, target.x, target.y);
			return;
		}
		Projectile p = new Projectile();
		p.kind = d.def.projectile;
		p.x = p.prevX = d.x;
		p.y = p.prevY = d.y;
		p.speed = d.def.projectileSpeed;
		p.source = d;
		p.target = target;
		p.targetX = target.x;
		p.targetY = target.y;
		p.type = type;
		p.strikes = strikes;
		projectiles.add(p);
	}

	private void moveProjectiles()
	{
		int write = 0;
		for (int read = 0, n = projectiles.size(); read < n; read++)
		{
			Projectile p = projectiles.get(read);
			if (p.target != null && !p.target.dead)
			{
				p.targetX = p.target.x;
				p.targetY = p.target.y;
			}
			double dx = p.targetX - p.x;
			double dy = p.targetY - p.y;
			double dist = Math.hypot(dx, dy);
			double travel = p.speed * STEP_SECONDS;
			p.prevX = p.x;
			p.prevY = p.y;
			if (dist <= travel)
			{
				boolean targetAlive = p.target != null && !p.target.dead;
				// A direct shot at something already dead fizzles. A splash still lands.
				if (targetAlive || p.source.stats.splash > 0)
				{
					impact(p.source, p.type, p.strikes, targetAlive ? p.target : null, p.targetX, p.targetY);
				}
				continue;
			}
			p.dirX = dx / dist;
			p.dirY = dy / dist;
			p.x += p.dirX * travel;
			p.y += p.dirY * travel;
			projectiles.set(write++, p);
		}
		while (projectiles.size() > write)
		{
			projectiles.remove(projectiles.size() - 1);
		}
	}

	private void impact(DefenderInstance d, DamageType type, int strikes, EnemyInstance target, double x, double y)
	{
		double splash = d.stats.splash;
		if (splash > 0)
		{
			FxEvent blast = emit(FxEvent.Kind.BLAST, x, y, 0);
			blast.sprite = d.def.blast;
			blast.radius = splash;
			double splashSq = splash * splash;
			for (int i = 0; i < enemies.size(); i++)
			{
				EnemyInstance e = enemies.get(i);
				double dx = e.x - x;
				double dy = e.y - y;
				if (!e.dead && dx * dx + dy * dy <= splashSq)
				{
					hit(d, e, type, strikes);
				}
			}
			return;
		}
		if (target == null || target.dead)
		{
			return;
		}
		if (!d.def.precise && target.def.evasion > 0 && rng.nextDouble() < target.def.evasion)
		{
			emit(FxEvent.Kind.MISS, target.x, target.y, 0);
			return;
		}
		hit(d, target, type, strikes);
	}

	private void hit(DefenderInstance d, EnemyInstance e, DamageType type, int strikes)
	{
		// Statuses land first, so a heavy strike benefits from its own armour crack and curse.
		applyStatuses(d.stats, e);
		boolean crit = d.stats.critChance > 0 && rng.nextDouble() < d.stats.critChance;
		double multiplier = e.weakenTimer > 0 ? 1 + e.weakenPercent : 1;
		if (crit)
		{
			multiplier *= d.stats.critMultiplier > 0 ? d.stats.critMultiplier : DEFAULT_CRIT_MULTIPLIER;
		}
		int dealt = 0;
		for (int s = 0; s < strikes; s++)
		{
			dealt += (int) Math.round(CombatSystem.damageFor(d.effectiveDamage(), type, e, d.stats.armourPierce) * multiplier);
		}
		e.hitAnim = HIT_ANIM_SECONDS;
		emit(crit ? FxEvent.Kind.CRIT : FxEvent.Kind.HIT, e.x, e.y, dealt);
		damage(e, dealt);
	}

	private void applyStatuses(Effects s, EnemyInstance e)
	{
		if (s.armourBreak > 0)
		{
			e.armourBroken = Math.max(e.armourBroken, s.armourBreak);
			e.armourBreakTimer = ARMOUR_BREAK_SECONDS;
		}
		if (s.burnDps > 0)
		{
			e.burnDps = e.burnTimer > 0 ? Math.max(e.burnDps, s.burnDps) : s.burnDps;
			e.burnTimer = s.burnSeconds;
		}
		if (s.slowPercent > 0)
		{
			double slow = Math.min(MAX_SLOW, s.slowPercent) * (e.def.boss ? 0.5 : 1);
			e.slowPercent = e.slowTimer > 0 ? Math.max(e.slowPercent, slow) : slow;
			e.slowTimer = s.slowSeconds;
		}
		if (s.rootChance > 0 && e.canBeBound() && rng.nextDouble() < s.rootChance)
		{
			e.rootTimer = s.rootSeconds;
			e.bindLockout = s.rootSeconds * BIND_LOCKOUT_RATIO;
		}
		if (s.weakenPercent > 0)
		{
			e.weakenPercent = e.weakenTimer > 0 ? Math.max(e.weakenPercent, s.weakenPercent) : s.weakenPercent;
			e.weakenTimer = s.weakenSeconds;
		}
	}

	/** All health loss goes through here, so a kill pays out exactly once, however it happens. */
	private void damage(EnemyInstance e, double amount)
	{
		e.hp -= amount;
		if (e.hp <= 0 && !e.dead)
		{
			e.dead = true;
			gold += (int) Math.round(e.def.goldReward * map.goldMultiplier);
			enemiesDefeated++;
			emit(FxEvent.Kind.DEATH, e.x, e.y, e.def.boss ? 2 : 1);
			if (e.def.splitCount > 0)
			{
				splitting.add(e);
			}
			if (map.deathHealRadius > 0)
			{
				healAround(e);
			}
		}
	}

	private void healAround(EnemyInstance fallen)
	{
		FxEvent blast = emit(FxEvent.Kind.BLAST, fallen.x, fallen.y, 0);
		blast.sprite = "blood_blast";
		blast.radius = map.deathHealRadius;
		double radiusSq = map.deathHealRadius * map.deathHealRadius;
		for (int i = 0; i < enemies.size(); i++)
		{
			EnemyInstance e = enemies.get(i);
			double dx = e.x - fallen.x;
			double dy = e.y - fallen.y;
			if (!e.dead && dx * dx + dy * dy <= radiusSq)
			{
				e.hp = Math.min(e.maxHp, e.hp + e.maxHp * map.deathHealPercent);
			}
		}
	}

	private void removeDeadEnemies()
	{
		int write = 0;
		for (int read = 0, n = enemies.size(); read < n; read++)
		{
			EnemyInstance e = enemies.get(read);
			if (!e.dead)
			{
				enemies.set(write++, e);
			}
		}
		while (enemies.size() > write)
		{
			enemies.remove(enemies.size() - 1);
		}
	}

	private boolean isWaveFinished()
	{
		if (!enemies.isEmpty())
		{
			return false;
		}
		WaveDefinition.Group[] groups = currentWave().groups;
		for (int i = 0; i < groups.length; i++)
		{
			if (spawned[i] < groups[i].count)
			{
				return false;
			}
		}
		return true;
	}

	private void finishWave()
	{
		projectiles.clear();
		gold += (int) Math.round(waveBonus(waveIndex) * map.goldMultiplier);
		waveIndex++;
		if (waveIndex >= map.waves.length)
		{
			endMatch(true);
			return;
		}
		autoStartTimer = autoStartDelay;
		state = State.WAVE_COMPLETE;
		checkpoint = buildCheckpoint();
	}

	/** Wave bonus by zero-based index, so the first wave clear pays 30 + 5 x 1. */
	public static int waveBonus(int index)
	{
		return 30 + 5 * (index + 1);
	}

	private void endMatch(boolean victory)
	{
		state = victory ? State.VICTORY : State.DEFEAT;
		checkpoint = null;
		if (matchEndListener != null)
		{
			matchEndListener.onMatchEnd(this, victory);
		}
	}

	private FxEvent emit(FxEvent.Kind kind, double x, double y, int value)
	{
		int slot = (fxHead + fxSize) % FX_CAPACITY;
		if (fxSize == FX_CAPACITY)
		{
			fxHead = (fxHead + 1) % FX_CAPACITY;
		}
		else
		{
			fxSize++;
		}
		FxEvent e = fx[slot];
		if (e == null)
		{
			e = fx[slot] = new FxEvent();
		}
		e.kind = kind;
		e.x = x;
		e.y = y;
		e.value = value;
		return e;
	}

	/** Returns the next pending visual event, or null. The returned object gets reused. */
	public FxEvent pollFx()
	{
		if (fxSize == 0)
		{
			return null;
		}
		FxEvent e = fx[fxHead];
		fxHead = (fxHead + 1) % FX_CAPACITY;
		fxSize--;
		return e;
	}

	// ---- Save and load ------------------------------------------------------

	/**
	 * The resume point for this match, or null if there is nothing to resume.
	 * Between waves it reflects the board now. Mid-wave it is the start of the wave,
	 * so reloading can't bank gold from a wave that was never finished.
	 */
	public MatchSave checkpoint()
	{
		if (!isMatchActive() || map == null)
		{
			return null;
		}
		boolean between = state == State.PREPARING || state == State.WAVE_COMPLETE
			|| (state == State.PAUSED && resumeState != State.RUNNING);
		return between ? buildCheckpoint() : checkpoint;
	}

	private MatchSave buildCheckpoint()
	{
		MatchSave s = new MatchSave();
		s.contentVersion = content.version;
		s.mapId = map.id;
		s.seed = seed;
		s.wave = waveIndex;
		s.gold = gold;
		s.baseHealth = baseHealth;
		s.goldSpent = goldSpent;
		s.enemiesDefeated = enemiesDefeated;
		s.ticks = ticks;
		for (int i = 0; i < defenders.size(); i++)
		{
			DefenderInstance d = defenders.get(i);
			MatchSave.SavedDefender sd = new MatchSave.SavedDefender();
			sd.id = d.def.id;
			sd.col = d.col;
			sd.row = d.row;
			sd.tierA = d.tierA;
			sd.tierB = d.tierB;
			sd.invested = d.invested;
			sd.targeting = d.targeting;
			s.defenders.add(sd);
		}
		return s;
	}

	/** Resumes a checkpoint, paused before its next wave. Returns false if the save is unusable. */
	public boolean restore(MatchSave s)
	{
		if (s == null || s.schemaVersion != MatchSave.SCHEMA || !content.version.equals(s.contentVersion))
		{
			return false;
		}
		MapDefinition m = content.map(s.mapId);
		if (m == null || s.wave < 0 || s.wave >= m.waves.length || s.gold < 0 || s.baseHealth <= 0)
		{
			return false;
		}
		List<DefenderInstance> restored = new ArrayList<>();
		for (MatchSave.SavedDefender sd : s.defenders)
		{
			DefenderDefinition def = content.defender(sd.id);
			if (def == null || !m.canFit(sd.col, sd.row, def.size) || sd.tierA < 0 || sd.tierB < 0
				|| sd.tierA > def.pathA.length || sd.tierB > def.pathB.length)
			{
				return false;
			}
			DefenderInstance d = new DefenderInstance(def, sd.col, sd.row);
			d.tierA = sd.tierA;
			d.tierB = sd.tierB;
			d.invested = sd.invested;
			d.targeting = sd.targeting == null ? def.targeting : sd.targeting;
			d.recalculate();
			for (DefenderInstance other : restored)
			{
				if (overlaps(d, other))
				{
					return false;
				}
			}
			restored.add(d);
		}
		loadMap(m, s.seed);
		defenders.addAll(restored);
		recalculateAuras();
		gold = s.gold;
		baseHealth = s.baseHealth;
		waveIndex = s.wave;
		goldSpent = s.goldSpent;
		enemiesDefeated = s.enemiesDefeated;
		ticks = s.ticks;
		state = State.PREPARING;
		checkpoint = null;
		return true;
	}

	private static boolean overlaps(DefenderInstance a, DefenderInstance b)
	{
		return a.col < b.col + b.def.size && b.col < a.col + a.def.size
			&& a.row < b.row + b.def.size && b.row < a.row + a.def.size;
	}

	// ---- Accessors ----------------------------------------------------------

	public void setMatchEndListener(MatchEndListener listener)
	{
		matchEndListener = listener;
	}

	public void setPlayerLevel(int level)
	{
		playerLevel = level;
	}

	/** Seconds before the next wave starts by itself; 0 for manual play. */
	public void setAutoStartDelay(double seconds)
	{
		if (seconds != autoStartDelay)
		{
			autoStartDelay = seconds;
			autoStartTimer = seconds;
		}
	}

	public double autoStartTimer()
	{
		return autoStartDelay > 0 ? autoStartTimer : 0;
	}

	public State state()
	{
		return state;
	}

	public Content content()
	{
		return content;
	}

	public MapDefinition map()
	{
		return map;
	}

	public List<DefenderInstance> defenders()
	{
		return defenders;
	}

	public List<EnemyInstance> enemies()
	{
		return enemies;
	}

	public List<Projectile> projectiles()
	{
		return projectiles;
	}

	public int gold()
	{
		return gold;
	}

	public int baseHealth()
	{
		return baseHealth;
	}

	/** Zero-based index of the current wave, or of the next one between waves. */
	public int waveIndex()
	{
		return waveIndex;
	}

	public int waveCount()
	{
		return map == null ? 0 : map.waves.length;
	}

	public int wavesCleared()
	{
		return waveIndex;
	}

	public WaveDefinition currentWave()
	{
		return map.waves[Math.min(waveIndex, map.waves.length - 1)];
	}

	public int goldSpent()
	{
		return goldSpent;
	}

	public int enemiesDefeated()
	{
		return enemiesDefeated;
	}

	public long ticks()
	{
		return ticks;
	}

	public int score()
	{
		return ScoreCalculator.score(wavesCleared(), baseHealth, enemiesDefeated, state == State.VICTORY);
	}
}

package com.runedefence.engine;

/** Turns distance along a map's waypoints into a position, in tile units. */
final class PathTable
{
	private final double[] xs;
	private final double[] ys;
	private final double[] start;
	final double length;

	PathTable(int[][] waypoints)
	{
		int n = waypoints.length;
		xs = new double[n];
		ys = new double[n];
		start = new double[n];
		for (int i = 0; i < n; i++)
		{
			xs[i] = waypoints[i][0] + 0.5;
			ys[i] = waypoints[i][1] + 0.5;
			if (i > 0)
			{
				start[i] = start[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
			}
		}
		length = start[n - 1];
	}

	void locate(double distance, EnemyInstance e)
	{
		int i = 0;
		while (i < xs.length - 2 && distance >= start[i + 1])
		{
			i++;
		}
		double t = (distance - start[i]) / (start[i + 1] - start[i]);
		t = Math.min(1, Math.max(0, t));
		e.x = xs[i] + (xs[i + 1] - xs[i]) * t;
		e.y = ys[i] + (ys[i + 1] - ys[i]) * t;
	}
}

package com.runedefence.engine;

import com.runedefence.model.DamageType;

public final class Projectile
{
	public String kind;
	public double x;
	public double y;
	public double prevX;
	public double prevY;
	/** Which way it was last moving, for drawing arrows at the right angle. */
	public double dirX;
	public double dirY;

	/** Whoever fired it, whose stats decide the hit even if it has since been sold. */
	DefenderInstance source;
	EnemyInstance target;
	double targetX;
	double targetY;
	double speed;
	DamageType type;
	int strikes;
}

package com.runedefence.engine;

/** Versioned, so that a later balance patch can't be compared against old scores. */
public final class ScoreCalculator
{
	public static final int VERSION = 2;

	private ScoreCalculator()
	{
	}

	public static int score(int wavesCleared, int baseHealth, int enemiesDefeated, boolean victory)
	{
		return wavesCleared * 100 + enemiesDefeated * 2 + baseHealth * 25 + (victory ? 5000 : 0);
	}
}

package com.runedefence.engine;

/**
 * Converts real elapsed time into fixed simulation steps. The cap on each advance
 * stops a stalled UI or a suspended laptop from fast-forwarding through waves.
 */
public final class SimulationClock
{
	static final long MAX_DELTA_MS = 250;
	private static final long STEP_MS = 50;

	private long accumulatorMs;

	/** Returns how many fixed steps to run for this much elapsed time. */
	public int advance(long deltaMs)
	{
		accumulatorMs += Math.max(0, Math.min(deltaMs, MAX_DELTA_MS));
		int steps = (int) (accumulatorMs / STEP_MS);
		accumulatorMs -= steps * STEP_MS;
		return steps;
	}

	/** How far between the last two steps to draw, 0 to 1. */
	public double alpha()
	{
		return accumulatorMs / (double) STEP_MS;
	}
}

package com.runedefence.model;

/** All game data, loaded from content.json. */
public final class Content
{
	public String version;
	public DefenderDefinition[] defenders;
	public EnemyDefinition[] enemies;
	public MapDefinition[] maps;

	public DefenderDefinition defender(String id)
	{
		for (DefenderDefinition d : defenders)
		{
			if (d.id.equals(id))
			{
				return d;
			}
		}
		return null;
	}

	/** The next defender a player of this level will unlock, or null if they have them all. */
	public DefenderDefinition nextUnlock(int level)
	{
		DefenderDefinition next = null;
		for (DefenderDefinition d : defenders)
		{
			if (d.requiredLevel > level && (next == null || d.requiredLevel < next.requiredLevel))
			{
				next = d;
			}
		}
		return next;
	}

	public EnemyDefinition enemy(String id)
	{
		for (EnemyDefinition e : enemies)
		{
			if (e.id.equals(id))
			{
				return e;
			}
		}
		return null;
	}

	public MapDefinition map(String id)
	{
		for (MapDefinition m : maps)
		{
			if (m.id.equals(id))
			{
				return m;
			}
		}
		return null;
	}
}

