/**
 * Draws the game and takes clicks on it. Gameplay stays in logical tile units;
 * pixels only exist in here, so resizing can never change how a match plays.
 */
final class BattlefieldPanel extends JComponent
{
	static final int NATIVE_TILE = 28;

	private static final double FX_LIFE = 0.6;
	private static final int FX_SLOTS = 48;
	private static final double CLICK_LIFE = 0.3;
	private static final double BANNER_LIFE = 2;
	private static final int FEET_BELOW_CENTRE = 8;
	private static final int SPRITE_FOOT_MARGIN = 3;
	private static final double RING_DIAMETER = 24;
	private static final int MONSTER_ICON = 18;

	interface Listener
	{
		/** Selection or placement mode changed. */
		void onFieldChanged();

		void onTutorialFinished();
	}

	private static final class ActiveFx
	{
		FxEvent.Kind kind;
		double x;
		double y;
		int value;
		String sprite;
		double radius;
		double age = FX_LIFE;
	}

	private static final String[] TUTORIAL = {
		"Welcome to RuneDefence!|Stop the raiders reaching the keep.|Leaks cost you health.",
		"Pick a defender from the shop,|then click open grass to place it.|Right-click to cancel.",
		"Kills and wave clears pay gold.|Spend it on defenders and upgrades.|Gold resets every match.",
		"Gaining XP in OSRS, in any skill,|raises your RuneDefence level and|unlocks new defenders. Good luck!"
	};

	private final GameEngine engine;
	private final SpriteAtlas atlas;
	private final Listener listener;
	private final ActiveFx[] fx = new ActiveFx[FX_SLOTS];

	private boolean[][] closed;
	private MapDefinition closedFor;
	private int closedLane;
	private BufferedImage terrain;
	private MapDefinition terrainMap;
	private int terrainTile;

	private MapDefinition menuMap;
	private boolean menuLocked;
	private Records.MapBest menuBest;
	private DefenderDefinition placing;
	private DefenderInstance selected;
	/** Mouse position in tile units; negative when it's off the field. */
	private double hoverX = -1;
	private double hoverY = -1;

	private double alpha;
	private double animTime;
	private boolean effects = true;
	private int tutorialStep = -1;

	private double clickAge = CLICK_LIFE;
	private double clickX;
	private double clickY;
	private boolean clickOk;

	private int bannerWave = -1;
	private double bannerAge = BANNER_LIFE;

	BattlefieldPanel(GameEngine engine, SpriteAtlas atlas, Listener listener)
	{
		this.engine = engine;
		this.atlas = atlas;
		this.listener = listener;
		for (int i = 0; i < FX_SLOTS; i++)
		{
			fx[i] = new ActiveFx();
		}
		menuMap = engine.content().maps[0];
		MapDefinition map = displayMap();
		setPreferredSize(new Dimension(map.columns * NATIVE_TILE, map.rows * NATIVE_TILE));
		setOpaque(true);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				hover(e);
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				hover(e);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hoverX = -1;
				hoverY = -1;
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				press(e);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	// ---- State --------------------------------------------------------------

	DefenderDefinition placing()
	{
		return placing;
	}

	void setPlacing(DefenderDefinition def)
	{
		placing = def;
		selected = null;
		listener.onFieldChanged();
	}

	DefenderInstance selected()
	{
		return selected;
	}

	void setSelected(DefenderInstance d)
	{
		selected = d;
		placing = null;
		listener.onFieldChanged();
	}

	void clearSelection()
	{
		if (selected != null || placing != null)
		{
			selected = null;
			placing = null;
			listener.onFieldChanged();
		}
	}

	/** What the map picker is showing, while there's no match. */
	void setMenu(MapDefinition map, boolean locked, Records.MapBest best)
	{
		menuMap = map;
		menuLocked = locked;
		menuBest = best;
	}

	void setEffects(boolean enabled)
	{
		effects = enabled;
	}

	void showTutorial()
	{
		tutorialStep = 0;
	}

	void setHover(int col, int row)
	{
		hoverX = col + 0.5;
		hoverY = row + 0.5;
	}

	/** Top left tile for a footprint centred on the mouse, nudged back onto the map at the edges. */
	private int anchor(double hover, int size, int limit)
	{
		int tile = (int) Math.floor(hover - size / 2.0 + 0.5);
		return Math.max(0, Math.min(tile, limit - size));
	}

	/** Advances visual-only timers. Effects freeze with the match when it is paused. */
	void animate(double seconds, double interpolation)
	{
		alpha = interpolation;
		FxEvent event;
		while ((event = engine.pollFx()) != null)
		{
			if (effects)
			{
				addFx(event);
			}
		}
		if (engine.state() == GameEngine.State.PAUSED)
		{
			alpha = 1;
			return;
		}
		animTime += seconds;
		clickAge += seconds;
		bannerAge += seconds;
		for (ActiveFx f : fx)
		{
			if (f.age < FX_LIFE)
			{
				f.age += seconds;
			}
		}
		if (engine.state() == GameEngine.State.RUNNING && bannerWave != engine.waveIndex())
		{
			bannerWave = engine.waveIndex();
			bannerAge = 0;
		}
	}

	private void addFx(FxEvent e)
	{
		// Takes the oldest slot, which caps the number of effects on screen.
		ActiveFx oldest = fx[0];
		for (ActiveFx f : fx)
		{
			if (f.age > oldest.age)
			{
				oldest = f;
			}
		}
		oldest.kind = e.kind;
		oldest.x = e.x;
		oldest.y = e.y;
		oldest.value = e.value;
		oldest.sprite = e.sprite;
		oldest.radius = e.radius;
		oldest.age = 0;
	}

	private MapDefinition displayMap()
	{
		return engine.map() != null ? engine.map() : menuMap;
	}

	private int tile()
	{
		MapDefinition m = displayMap();
		return Math.max(1, Math.min(getWidth() / m.columns, getHeight() / m.rows));
	}

	private int originX(int tile)
	{
		return (getWidth() - displayMap().columns * tile) / 2;
	}

	private int originY(int tile)
	{
		return (getHeight() - displayMap().rows * tile) / 2;
	}

	// ---- Input --------------------------------------------------------------

	private void hover(MouseEvent e)
	{
		int tile = tile();
		hoverX = (e.getX() - originX(tile)) / (double) tile;
		hoverY = (e.getY() - originY(tile)) / (double) tile;
	}

	private void press(MouseEvent e)
	{
		hover(e);
		if (tutorialStep >= 0)
		{
			tutorialStep++;
			if (tutorialStep >= TUTORIAL.length)
			{
				tutorialStep = -1;
				listener.onTutorialFinished();
			}
			return;
		}
		if (SwingUtilities.isRightMouseButton(e))
		{
			clearSelection();
			return;
		}
		if (engine.map() == null)
		{
			return;
		}
		if (placing != null)
		{
			MapDefinition m = engine.map();
			int col = anchor(hoverX, placing.size, m.columns);
			int row = anchor(hoverY, placing.size, m.rows);
			boolean ok = engine.place(placing.id, col, row) == GameEngine.Result.OK;
			showClick(ok, col + placing.size / 2.0, row + placing.size / 2.0);
			if (ok)
			{
				placing = null;
				listener.onFieldChanged();
			}
			return;
		}
		DefenderInstance d = engine.defenderAt((int) Math.floor(hoverX), (int) Math.floor(hoverY));
		if (d != null)
		{
			setSelected(d);
		}
		else
		{
			clearSelection();
		}
	}

	private void showClick(boolean ok, double x, double y)
	{
		clickOk = ok;
		clickAge = 0;
		clickX = x;
		clickY = y;
	}

	// ---- Painting -----------------------------------------------------------

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.setColor(Theme.STONE_EDGE);
		g.fillRect(0, 0, getWidth(), getHeight());

		int tile = tile();
		int ox = originX(tile);
		int oy = originY(tile);
		MapDefinition map = displayMap();
		if (terrain == null || terrainMap != map || terrainTile != tile)
		{
			terrain = Terrain.render(map, atlas, tile);
			terrainMap = map;
			terrainTile = tile;
		}
		g.drawImage(terrain, ox, oy, null);
		g.translate(ox, oy);
		g.setFont(Theme.small());

		if (engine.map() != null)
		{
			paintClosedRoutes(g, tile);
			paintPlacement(g, tile);
			paintSelection(g, tile);
			paintDefenders(g, tile);
			paintEnemies(g, tile);
			paintProjectiles(g, tile);
			paintFx(g, tile);
			paintClick(g, tile);
		}
		paintOverlays(g, tile, map);
		g.translate(-ox, -oy);
	}

	/** Where the route shifts, the corridors not in use go dark. */
	private void paintClosedRoutes(Graphics2D g, int tile)
	{
		MapDefinition m = engine.map();
		int lane = engine.activeLane();
		if (lane < 0)
		{
			return;
		}
		if (closedFor != m || closedLane != lane)
		{
			closedFor = m;
			closedLane = lane;
			closed = new boolean[m.rows][m.columns];
			for (int row = 0; row < m.rows; row++)
			{
				for (int col = 0; col < m.columns; col++)
				{
					closed[row][col] = m.isOnPath(col, row) && !m.isOnLane(lane, col, row);
				}
			}
		}
		g.setColor(Theme.CLOSED_ROUTE);
		for (int row = 0; row < m.rows; row++)
		{
			for (int col = 0; col < m.columns; col++)
			{
				if (closed[row][col])
				{
					g.fillRect(col * tile, row * tile, tile, tile);
				}
			}
		}
	}

	private void paintPlacement(Graphics2D g, int tile)
	{
		if (placing == null || hoverX < 0 || hoverY < 0)
		{
			return;
		}
		MapDefinition m = engine.map();
		if (hoverX >= m.columns || hoverY >= m.rows)
		{
			return;
		}
		int size = placing.size;
		int col = anchor(hoverX, size, m.columns);
		int row = anchor(hoverY, size, m.rows);
		g.setColor(engine.canPlaceAt(size, col, row) ? Theme.VALID_FILL : Theme.INVALID_FILL);
		g.fillRect(col * tile, row * tile, size * tile, size * tile);
		paintRange(g, col + size / 2.0, row + size / 2.0, placing.rangeTiles, tile);
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.65f));
		g.drawImage(atlas.frame(placing.id, 0), col * tile, row * tile - 2, size * tile, size * tile, null);
		g.setComposite(old);
	}

	private void paintSelection(Graphics2D g, int tile)
	{
		if (selected == null)
		{
			return;
		}
		paintRange(g, selected.x, selected.y, selected.range, tile);
		g.setColor(Theme.SELECT_LINE);
		int span = selected.def.size * tile;
		g.drawRect(selected.col * tile, selected.row * tile, span - 1, span - 1);
	}

	private static void paintRange(Graphics2D g, double x, double y, double range, int tile)
	{
		int r = (int) (range * tile);
		int cx = (int) (x * tile);
		int cy = (int) (y * tile);
		g.setColor(Theme.RANGE_FILL);
		g.fillOval(cx - r, cy - r, r * 2, r * 2);
		g.setColor(Theme.RANGE_LINE);
		g.drawOval(cx - r, cy - r, r * 2, r * 2);
	}

	private void paintDefenders(Graphics2D g, int tile)
	{
		BufferedImage pad = atlas.frame("pad", 0);
		List<DefenderInstance> list = engine.defenders();
		for (int i = 0; i < list.size(); i++)
		{
			DefenderInstance d = list.get(i);
			int x = d.col * tile;
			int y = d.row * tile;
			int span = d.def.size * tile;
			g.drawImage(pad, x, y, span, span, null);
			int frame;
			if (d.stunTimer > 0)
			{
				frame = 0;
			}
			else if (d.attackAnim > 0.12)
			{
				frame = 2;
			}
			else if (d.attackAnim > 0)
			{
				frame = 3;
			}
			else
			{
				// Each defender breathes slightly out of step with its neighbours.
				frame = (int) ((animTime + (d.col + d.row) * 0.17) / 0.6) % 2;
			}
			drawFacing(g, atlas.frame(d.def.id, frame), x, y - tile / 14, span, span, d.facingLeft);
			if (d.stunTimer > 0)
			{
				// Petrified: frozen on one frame, under a skin of stone.
				g.setColor(Theme.PETRIFIED);
				g.fillOval(x + span / 8, y, span * 3 / 4, span - 2);
			}
			int tiers = d.tierA + d.tierB;
			for (int t = 0; t < tiers; t++)
			{
				g.setColor(Color.BLACK);
				g.fillRect(x + 1, y + span - 4 - t * 4, 3, 3);
				g.setColor(Theme.YELLOW);
				g.fillRect(x + 1, y + span - 4 - t * 4, 2, 2);
			}
		}
	}

	private static void drawFacing(Graphics2D g, BufferedImage image, int x, int y, int w, int h, boolean left)
	{
		if (left)
		{
			g.drawImage(image, x + w, y, -w, h, null);
		}
		else
		{
			g.drawImage(image, x, y, w, h, null);
		}
	}

	private void paintEnemies(Graphics2D g, int tile)
	{
		List<EnemyInstance> list = engine.enemies();
		for (int i = 0; i < list.size(); i++)
		{
			EnemyInstance e = list.get(i);
			double x = (e.prevX + (e.x - e.prevX) * alpha + e.laneOffset) * tile;
			double y = (e.prevY + (e.y - e.prevY) * alpha + e.laneOffset) * tile;
			SpriteAtlas.Sprite sprite = atlas.get(e.def.id);
			int w = sprite.width * tile / NATIVE_TILE;
			int h = sprite.height * tile / NATIVE_TILE;
			int left = (int) x - w / 2;
			int top = (int) y + FEET_BELOW_CENTRE * tile / NATIVE_TILE - h + SPRITE_FOOT_MARGIN;
			if (e.isRooted())
			{
				// A snare around its feet, big enough to see at a glance in a crowd.
				int ringWidth = Math.max(w * 3 / 4, tile * 2 / 3);
				g.setColor(Theme.BIND_FILL);
				g.fillOval((int) x - ringWidth / 2, top + h - tile / 4, ringWidth, tile / 3);
				g.setColor(Theme.BIND_LINE);
				g.drawOval((int) x - ringWidth / 2, top + h - tile / 4, ringWidth, tile / 3);
			}
			drawFacing(g, sprite.frames[(int) (e.progress * 5) % sprite.frames.length], left, top, w, h, e.facingLeft);
			paintStatuses(g, e, (int) x, top + 1);
			if (e.hp < e.maxHp)
			{
				paintHealthBar(g, (int) x, top - 3, e.def.boss ? 30 : 18, e.hp / e.maxHp);
			}
		}
	}

	/** A row of coloured chips over the head, one for each thing currently affecting it. */
	private static void paintStatuses(Graphics2D g, EnemyInstance e, int cx, int y)
	{
		int x = cx - 8;
		x = chip(g, e.isArmourBroken(), Theme.ORANGE, x, y);
		x = chip(g, e.isBurning(), Theme.BURN_CHIP, x, y);
		x = chip(g, e.isSlowed(), Theme.SLOW_CHIP, x, y);
		x = chip(g, e.isRooted(), Theme.ROOT_CHIP, x, y);
		chip(g, e.isWeakened(), Theme.CURSE_CHIP, x, y);
	}

	private static int chip(Graphics2D g, boolean on, Color colour, int x, int y)
	{
		if (!on)
		{
			return x;
		}
		g.setColor(Color.BLACK);
		g.fillRect(x, y, 4, 4);
		g.setColor(colour);
		g.fillRect(x, y, 3, 3);
		return x + 4;
	}

	private static void paintHealthBar(Graphics2D g, int cx, int y, int w, double fraction)
	{
		int left = cx - w / 2;
		g.setColor(Theme.HP_RED);
		g.fillRect(left, y, w, 3);
		g.setColor(Theme.HP_GREEN);
		g.fillRect(left, y, (int) Math.ceil(w * Math.max(0, fraction)), 3);
	}

	private void paintProjectiles(Graphics2D g, int tile)
	{
		List<Projectile> list = engine.projectiles();
		for (int i = 0; i < list.size(); i++)
		{
			Projectile p = list.get(i);
			int x = (int) ((p.prevX + (p.x - p.prevX) * alpha) * tile);
			int y = (int) ((p.prevY + (p.y - p.prevY) * alpha) * tile) - tile / 7;
			switch (p.kind)
			{
				case "arrow":
					paintShaft(g, x, y, p.dirX, p.dirY, 8, Theme.ARROW_SHAFT, Color.WHITE);
					break;
				case "dart":
					paintShaft(g, x, y, p.dirX, p.dirY, 5, Theme.DART_SHAFT, Theme.DART_TIP);
					break;
				default:
					BufferedImage image = atlas.frame(p.kind, (int) (animTime * 12));
					g.drawImage(image, x - image.getWidth() / 2, y - image.getHeight() / 2, null);
					break;
			}
		}
	}

	private static void paintShaft(Graphics2D g, int x, int y, double dx, double dy, int length, Color shaft, Color tip)
	{
		int tx = x - (int) (dx * length);
		int ty = y - (int) (dy * length);
		g.setColor(Color.BLACK);
		g.drawLine(x, y + 1, tx, ty + 1);
		g.setColor(shaft);
		g.drawLine(x, y, tx, ty);
		g.setColor(tip);
		g.fillRect(x, y, 2, 2);
	}

	private void paintFx(Graphics2D g, int tile)
	{
		// Puffs and blasts go underneath, so hit numbers are always readable.
		for (ActiveFx f : fx)
		{
			if (f.age >= FX_LIFE)
			{
				continue;
			}
			if (f.kind == FxEvent.Kind.BLAST)
			{
				paintBlast(g, f, tile);
			}
			else if (f.kind == FxEvent.Kind.DEATH)
			{
				paintBurst(g, "dust", f, tile, f.value);
			}
		}
		for (ActiveFx f : fx)
		{
			if (f.age >= FX_LIFE)
			{
				continue;
			}
			if (f.kind == FxEvent.Kind.HIT || f.kind == FxEvent.Kind.LEAK)
			{
				paintSplat(g, f, tile, Theme.SPLAT_RED, Theme.SPLAT_RED_DARK);
			}
			else if (f.kind == FxEvent.Kind.CRIT)
			{
				paintSplat(g, f, tile, Theme.SPLAT_GOLD, Theme.SPLAT_GOLD_DARK);
			}
			else if (f.kind == FxEvent.Kind.GAZE)
			{
				int r = tile / 2 + (int) (f.age * 20);
				g.setColor(Theme.YELLOW);
				g.drawOval((int) (f.x * tile) - r, (int) (f.y * tile) - r, r * 2, r * 2);
			}
			else if (f.kind == FxEvent.Kind.MISS)
			{
				paintSplat(g, f, tile, Theme.SPLAT_BLUE, Theme.SPLAT_BLUE_DARK);
			}
		}
	}

	/** The ring is drawn at the real blast radius, so players can see what it reached. */
	private void paintBlast(Graphics2D g, ActiveFx f, int tile)
	{
		SpriteAtlas.Sprite s = atlas.get(f.sprite);
		int frame = Math.min(s.frames.length - 1, (int) (f.age / FX_LIFE * s.frames.length));
		int size = (int) (f.radius * 2 * tile * s.width / RING_DIAMETER);
		g.drawImage(s.frames[frame], (int) (f.x * tile) - size / 2, (int) (f.y * tile) - size / 2, size, size, null);
	}

	private void paintBurst(Graphics2D g, String name, ActiveFx f, int tile, int scale)
	{
		SpriteAtlas.Sprite s = atlas.get(name);
		int frame = Math.min(s.frames.length - 1, (int) (f.age / FX_LIFE * s.frames.length));
		int w = s.width * scale * tile / NATIVE_TILE;
		int h = s.height * scale * tile / NATIVE_TILE;
		g.drawImage(s.frames[frame], (int) (f.x * tile) - w / 2, (int) (f.y * tile) - h / 2, w, h, null);
	}

	private void paintSplat(Graphics2D g, ActiveFx f, int tile, Color face, Color edge)
	{
		// Only shown for the first half of its life, like a hit marker, and rises slightly.
		if (f.age > FX_LIFE * 0.7)
		{
			return;
		}
		int cx = (int) (f.x * tile);
		int cy = (int) (f.y * tile) - tile / 3 - (int) (f.age * 8);
		String value = Integer.toString(f.kind == FxEvent.Kind.MISS ? 0 : f.value);
		// Wide enough for the big numbers late-game hits reach.
		int half = Math.max(7, g.getFontMetrics().stringWidth(value) / 2 + 3);
		g.setColor(edge);
		g.fillRect(cx - half, cy - 4, half * 2, 9);
		g.fillRect(cx - half + 2, cy - 6, half * 2 - 4, 13);
		g.setColor(face);
		g.fillRect(cx - half + 1, cy - 3, half * 2 - 2, 7);
		g.fillRect(cx - half + 3, cy - 5, half * 2 - 6, 11);
		Theme.centered(g, value, cx, cy + 4, Color.WHITE);
	}

	private void paintClick(Graphics2D g, int tile)
	{
		if (clickAge >= CLICK_LIFE)
		{
			return;
		}
		int size = 7 - (int) (clickAge / CLICK_LIFE * 5);
		int cx = (int) (clickX * tile);
		int cy = (int) (clickY * tile);
		g.setColor(clickOk ? Theme.YELLOW : Theme.RED);
		g.drawLine(cx - size, cy - size, cx + size, cy + size);
		g.drawLine(cx - size, cy + size, cx + size, cy - size);
		g.drawLine(cx - size + 1, cy - size, cx + size + 1, cy + size);
		g.drawLine(cx - size + 1, cy + size, cx + size + 1, cy - size);
	}

	private void paintOverlays(Graphics2D g, int tile, MapDefinition map)
	{
		int w = map.columns * tile;
		int h = map.rows * tile;
		GameEngine.State state = engine.state();
		if (tutorialStep >= 0)
		{
			paintTutorial(g, w, h);
			return;
		}
		switch (state)
		{
			case MENU:
				paintMapPicker(g, w, h, map);
				break;
			case PAUSED:
				paintBox(g, w, h / 2 - 22, 38, Theme.DIM_OVERLAY);
				g.setFont(Theme.bold());
				Theme.centered(g, "Paused", w / 2, h / 2 + 2, Theme.YELLOW);
				break;
			case VICTORY:
			case DEFEAT:
				paintEnd(g, w, h, state == GameEngine.State.VICTORY);
				break;
			case PREPARING:
			case WAVE_COMPLETE:
				paintNextWave(g, w);
				break;
			default:
				break;
		}
		if (state == GameEngine.State.RUNNING && bannerAge < BANNER_LIFE)
		{
			paintBanner(g, w, h);
		}
	}

	private void paintMapPicker(Graphics2D g, int w, int h, MapDefinition map)
	{
		paintBox(g, w, h / 2 - 76, 150, Theme.PANEL_OVERLAY);
		g.setFont(Theme.bold());
		Theme.centered(g, map.name, w / 2, h / 2 - 54, Theme.ORANGE);
		g.setFont(Theme.small());
		int y = h / 2 - 34;
		for (String line : map.description)
		{
			Theme.centered(g, line, w / 2, y, Theme.TEXT);
			y += 15;
		}
		y = h / 2 + 22;
		Theme.centered(g, map.waves.length + " waves, " + map.startingGold + " starting gold", w / 2, y, Theme.YELLOW);
		y += 16;
		if (menuLocked)
		{
			Theme.centered(g, "Unlocks at RuneDefence level " + map.requiredLevel, w / 2, y, Theme.RED);
		}
		else if (menuBest != null)
		{
			Theme.centered(g, "Best wave " + menuBest.bestWave + ", best score " + menuBest.bestScore, w / 2, y, Theme.GREEN);
		}
		else
		{
			Theme.centered(g, "Not played yet", w / 2, y, Theme.TEXT_DIM);
		}
		paintMonsterIcons(g, map, w, y + 6);
	}

	/** A row of the monsters this map can send, drawn small enough for the longest list to fit. */
	private void paintMonsterIcons(Graphics2D g, MapDefinition map, int w, int y)
	{
		int count = map.monsters.length;
		int step = Math.min(MONSTER_ICON + 2, (w - 8) / Math.max(1, count));
		int x = (w - step * count) / 2;
		for (String id : map.monsters)
		{
			g.drawImage(atlas.get(id).frames[0], x, y, Math.min(step, MONSTER_ICON), Math.min(step, MONSTER_ICON), null);
			x += step;
		}
	}

	private static void paintBox(Graphics2D g, int w, int y, int height, Color c)
	{
		g.setColor(c);
		g.fillRect(0, y, w, height);
		g.setColor(Theme.STONE_LIGHT);
		g.drawLine(0, y, w, y);
		g.drawLine(0, y + height - 1, w, y + height - 1);
	}

	private void paintEnd(Graphics2D g, int w, int h, boolean victory)
	{
		paintBox(g, w, h / 2 - 66, 112, Theme.PANEL_OVERLAY);
		g.setFont(Theme.bold());
		Theme.centered(g, victory ? "Victory!" : "The keep has fallen", w / 2, h / 2 - 40, victory ? Theme.GREEN : Theme.RED);
		g.setFont(Theme.small());
		Theme.centered(g, "Waves cleared: " + engine.wavesCleared() + "/" + engine.waveCount(), w / 2, h / 2 - 20, Theme.TEXT);
		Theme.centered(g, "Enemies defeated: " + engine.enemiesDefeated(), w / 2, h / 2 - 4, Theme.TEXT);
		Theme.centered(g, "Gold spent: " + engine.goldSpent(), w / 2, h / 2 + 12, Theme.TEXT);
		Theme.centered(g, "Score: " + engine.score(), w / 2, h / 2 + 32, Theme.YELLOW);
	}

	private void paintNextWave(Graphics2D g, int w)
	{
		WaveDefinition wave = engine.currentWave();
		g.setColor(Theme.DIM_OVERLAY);
		g.fillRect(0, 0, w, 20);
		g.setFont(Theme.small());
		if (engine.state() == GameEngine.State.WAVE_COMPLETE && engine.map().isMilestone(engine.wavesCleared()))
		{
			g.setFont(Theme.bold());
			Theme.centered(g, "Wave " + engine.wavesCleared() + " defeated!", w / 2, 44, Theme.GREEN);
			g.setFont(Theme.small());
			Theme.centered(g, "They're only getting stronger...", w / 2, 60, Theme.ORANGE);
		}
		else if (engine.map().rotateLanesEvery > 0 && engine.waveIndex() > 0 && engine.waveIndex() % engine.map().rotateLanesEvery == 0)
		{
			g.setFont(Theme.small());
			Theme.centered(g, "The route has shifted!", w / 2, 36, Theme.ORANGE);
		}
		Theme.text(g, "Next:", 3, 14, Theme.YELLOW);
		int x = 34;
		for (WaveDefinition.Group group : wave.groups)
		{
			String count = group.count + "x";
			Theme.text(g, count, x, 14, Theme.TEXT);
			x += g.getFontMetrics().stringWidth(count) + 1;
			SpriteAtlas.Sprite s = atlas.get(group.enemy);
			g.drawImage(s.frames[0], x, 1, 18, 18, null);
			x += 21;
		}
	}

	private void paintBanner(Graphics2D g, int w, int h)
	{
		Composite old = g.getComposite();
		float fade = (float) Math.min(1, (BANNER_LIFE - bannerAge) * 2);
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, fade)));
		g.setFont(Theme.bold());
		String text = "Wave " + (engine.waveIndex() + 1);
		boolean boss = false;
		for (WaveDefinition.Group group : engine.currentWave().groups)
		{
			if (engine.content().enemy(group.enemy).boss)
			{
				boss = true;
			}
		}
		Theme.centered(g, text, w / 2, 44, boss ? Theme.RED : Theme.YELLOW);
		if (boss)
		{
			g.setFont(Theme.small());
			Theme.centered(g, "A champion approaches!", w / 2, 60, Theme.ORANGE);
		}
		g.setComposite(old);
	}

	private void paintTutorial(Graphics2D g, int w, int h)
	{
		paintBox(g, w, h / 2 - 60, 110, Theme.PANEL_OVERLAY);
		g.setFont(Theme.small());
		String[] lines = TUTORIAL[tutorialStep].split("\\|");
		int y = h / 2 - 34;
		for (int i = 0; i < lines.length; i++)
		{
			Theme.centered(g, lines[i], w / 2, y, i == 0 && tutorialStep == 0 ? Theme.ORANGE : Theme.TEXT);
			y += 18;
		}
		Theme.centered(g, "Click to continue (" + (tutorialStep + 1) + "/" + TUTORIAL.length + ")", w / 2, y + 12, Theme.YELLOW);
	}
}

package com.runedefence.ui;

import com.runedefence.engine.DefenderInstance;
import com.runedefence.engine.GameEngine;
import com.runedefence.model.UpgradeDefinition;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.util.Locale;
import javax.swing.JComponent;
import javax.swing.JPanel;

/** Upgrade, retarget or sell the selected defender. */
final class DefenderDock extends JPanel
{
	private final GameEngine engine;
	private final BattlefieldPanel field;
	private final Runnable onChanged;
	private final StoneButton[] paths = {new StoneButton(""), new StoneButton("")};
	private final StoneButton target = new StoneButton("");
	private final StoneButton sell = new StoneButton("");
	private final Title title = new Title();

	DefenderDock(GameEngine engine, BattlefieldPanel field, Runnable onChanged)
	{
		super(new BorderLayout());
		this.engine = engine;
		this.field = field;
		this.onChanged = onChanged;
		setBackground(Theme.STONE_DARK);

		JPanel rows = new JPanel(new GridLayout(3, 1, 0, 1));
		rows.setOpaque(false);
		for (int i = 0; i < paths.length; i++)
		{
			int path = i;
			paths[i].addActionListener(e -> upgrade(path));
			rows.add(paths[i]);
		}
		JPanel bottom = new JPanel(new GridLayout(1, 2, 1, 0));
		bottom.setOpaque(false);
		target.addActionListener(e -> retarget());
		sell.addActionListener(e -> sellSelected());
		bottom.add(target);
		bottom.add(sell);
		rows.add(bottom);

		add(title, BorderLayout.NORTH);
		add(rows, BorderLayout.CENTER);
	}

	private void upgrade(int path)
	{
		DefenderInstance d = field.selected();
		if (d != null && engine.upgrade(d, path) == GameEngine.Result.OK)
		{
			onChanged.run();
		}
	}

	private void retarget()
	{
		DefenderInstance d = field.selected();
		if (d != null)
		{
			engine.cycleTargeting(d);
			onChanged.run();
		}
	}

	private void sellSelected()
	{
		DefenderInstance d = field.selected();
		if (d != null && engine.sell(d) == GameEngine.Result.OK)
		{
			field.clearSelection();
			onChanged.run();
		}
	}

	void refresh()
	{
		DefenderInstance d = field.selected();
		if (d == null)
		{
			return;
		}
		for (int i = 0; i < paths.length; i++)
		{
			UpgradeDefinition next = GameEngine.nextUpgrade(d, i);
			if (next == null)
			{
				paths[i].setLabel("Path complete", null);
				paths[i].setEnabled(false);
			}
			else if (GameEngine.isPathBlocked(d, i))
			{
				paths[i].setLabel("Locked by other path", "Only one path can reach its second upgrade");
				paths[i].setEnabled(false);
			}
			else
			{
				boolean afford = engine.gold() >= next.cost && engine.isMatchActive();
				paths[i].setLabel(next.name + " (" + next.cost + "g)", upgradeTip(d, next, i));
				paths[i].setTextColour(afford ? Theme.YELLOW : Theme.RED);
				paths[i].setEnabled(engine.isMatchActive());
			}
		}
		target.setLabel("Target: " + d.targeting.label(), "Which enemy in range to attack. Click to change.");
		sell.setLabel("Sell (" + GameEngine.sellValue(d) + "g)", "Refunds 70% of the gold spent on this defender");
		sell.setEnabled(engine.isMatchActive());
		title.repaint();
	}

	/** What this upgrade would do to this defender, as it stands on this board. */
	private String upgradeTip(DefenderInstance d, UpgradeDefinition next, int path)
	{
		StringBuilder tip = new StringBuilder("<html>").append(next.description);
		double speedBoost = (1 + d.auraSpeed) * engine.map().defenderSpeed;
		for (String effect : DefenderText.upgradeEffects(d.def, d.tierA, d.tierB, path, 1 + d.auraDamage, speedBoost))
		{
			tip.append("<br>").append(effect.replace(">", "&gt;"));
		}
		return tip.append("</html>").toString();
	}

	private final class Title extends JComponent
	{
		Title()
		{
			setPreferredSize(new Dimension(224, 17));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			DefenderInstance d = field.selected();
			if (d == null)
			{
				return;
			}
			Graphics2D g = (Graphics2D) graphics;
			g.setFont(Theme.small());
			Theme.text(g, d.def.name, 4, 13, Theme.ORANGE);
			setToolTipText("Damage, seconds between attacks (lower is faster) and range. Green means a nearby ally is boosting it.");
			String stats = String.format(Locale.ROOT, "%d  %s  %.1f", d.effectiveDamage(), DefenderText.seconds(engine.attackInterval(d)), d.range);
			boolean boosted = d.auraDamage > 0 || d.auraSpeed > 0;
			Theme.text(g, stats, getWidth() - g.getFontMetrics().stringWidth(stats) - 4, 13, boosted ? Theme.GREEN : Theme.TEXT);
		}
	}
}

package com.runedefence.ui;

import com.runedefence.engine.DefenderInstance;
import com.runedefence.engine.GameEngine;
import com.runedefence.model.DamageType;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.Effects;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Describes defenders and upgrades in exact numbers. Everything comes from previewing
 * the real defender, so the words can't drift away from what the engine does.
 */
final class DefenderText
{
	/** The font has no arrow glyph. */
	private static final String TO = " -> ";

	private DefenderText()
	{
	}

	/** A defender before any upgrades, in the order a player would ask about them. */
	static List<String> baseStats(DefenderDefinition d)
	{
		DefenderInstance base = DefenderInstance.preview(d, 0, 0);
		List<String> lines = new ArrayList<>();
		lines.add("Damage: " + base.damage + " " + damageKind(d));
		lines.add("Attacks every " + seconds(1 / base.attacksPerSecond));
		lines.add("Range: " + tiles(base.range));
		lines.addAll(effectChanges(new Effects(), base.stats));
		if (d.precise)
		{
			lines.add("Its attacks can't be dodged");
		}
		if (d.seeksUnbound)
		{
			lines.add("Goes for enemies it can still bind");
		}
		return lines;
	}

	/** The exact effect of the next upgrade on a path, on its own. */
	static List<String> upgradeEffects(DefenderDefinition d, int tierA, int tierB, int path)
	{
		return upgradeEffects(d, tierA, tierB, path, 1, 1);
	}

	/** As above, for a defender on the board, whose auras and map change its real numbers. */
	static List<String> upgradeEffects(DefenderDefinition d, int tierA, int tierB, int path, double damageBoost, double speedBoost)
	{
		DefenderInstance before = DefenderInstance.preview(d, tierA, tierB);
		DefenderInstance after = DefenderInstance.preview(d, path == 0 ? tierA + 1 : tierA, path == 1 ? tierB + 1 : tierB);
		List<String> lines = new ArrayList<>();
		if (after.damage != before.damage)
		{
			lines.add("Damage " + Math.round(before.damage * damageBoost) + TO + Math.round(after.damage * damageBoost));
		}
		if (after.attacksPerSecond != before.attacksPerSecond)
		{
			lines.add("Attacks every " + seconds(1 / (before.attacksPerSecond * speedBoost)) + TO + seconds(1 / (after.attacksPerSecond * speedBoost)));
		}
		if (after.range != before.range)
		{
			lines.add("Range " + number(before.range) + TO + tiles(after.range));
		}
		lines.addAll(effectChanges(before.stats, after.stats));
		return lines;
	}

	/** Whether anything on this defender, base or upgraded, can bind. */
	static boolean canBind(DefenderDefinition d)
	{
		for (int path = 0; path < 2; path++)
		{
			for (int tier = 0; tier < DefenderDefinition.TIERS; tier++)
			{
				if (d.path(path)[tier].rootChance > 0)
				{
					return true;
				}
			}
		}
		return d.rootChance > 0;
	}

	static String seconds(double value)
	{
		return String.format(Locale.ROOT, "%.2fs", value);
	}

	private static String damageKind(DefenderDefinition d)
	{
		if (d.alternatesDamage)
		{
			return "physical and magic in turn";
		}
		return d.damageType == DamageType.MAGIC ? "magic" : "physical";
	}

	private static List<String> effectChanges(Effects a, Effects b)
	{
		List<String> lines = new ArrayList<>();
		if (b.splash != a.splash)
		{
			lines.add(a.splash == 0 ? "Hits everything within " + tiles(b.splash) : "Blast radius " + number(a.splash) + TO + tiles(b.splash));
		}
		if (b.armourPierce != a.armourPierce)
		{
			lines.add(a.armourPierce == 0 ? "Ignores " + b.armourPierce + " armour" : "Ignores " + a.armourPierce + TO + b.armourPierce + " armour");
		}
		if (b.armourBreak != a.armourBreak)
		{
			lines.add(a.armourBreak == 0
				? "Cracks " + b.armourBreak + " armour for " + number(GameEngine.ARMOUR_BREAK_SECONDS) + "s"
				: "Cracks " + a.armourBreak + TO + b.armourBreak + " armour");
		}
		if (b.strikeEvery != a.strikeEvery)
		{
			lines.add("Every " + ordinal(b.strikeEvery) + " attack strikes twice");
		}
		if (b.critChance != a.critChance)
		{
			lines.add(a.critChance == 0
				? percent(b.critChance) + " chance of " + number(b.critMultiplier > 0 ? b.critMultiplier : GameEngine.DEFAULT_CRIT_MULTIPLIER) + "x damage"
				: "Critical chance " + percent(a.critChance) + TO + percent(b.critChance));
		}
		burn(a, b, lines);
		slow(a, b, lines);
		bind(a, b, lines);
		if (b.weakenPercent != a.weakenPercent)
		{
			lines.add(a.weakenPercent == 0
				? "Cursed foes take " + percent(b.weakenPercent) + " more damage for " + number(b.weakenSeconds) + "s"
				: "Cursed foes take " + percent(a.weakenPercent) + TO + percent(b.weakenPercent) + " more");
		}
		aura(a, b, lines);
		return lines;
	}

	private static void burn(Effects a, Effects b, List<String> lines)
	{
		if (a.burnDps == 0 && b.burnDps > 0)
		{
			lines.add("Burns for " + number(b.burnDps) + " a second for " + number(b.burnSeconds) + "s");
			return;
		}
		if (b.burnDps != a.burnDps)
		{
			lines.add("Burn " + number(a.burnDps) + TO + number(b.burnDps) + " a second");
		}
		if (b.burnSeconds != a.burnSeconds)
		{
			lines.add("Burn lasts " + number(a.burnSeconds) + "s" + TO + number(b.burnSeconds) + "s");
		}
	}

	private static void slow(Effects a, Effects b, List<String> lines)
	{
		if (a.slowPercent == 0 && b.slowPercent > 0)
		{
			lines.add("Slows by " + percent(b.slowPercent) + " for " + number(b.slowSeconds) + "s");
			return;
		}
		if (b.slowPercent != a.slowPercent)
		{
			lines.add("Slow " + percent(a.slowPercent) + TO + percent(b.slowPercent));
		}
		if (b.slowSeconds != a.slowSeconds)
		{
			lines.add("Slow lasts " + number(a.slowSeconds) + "s" + TO + number(b.slowSeconds) + "s");
		}
	}

	private static void bind(Effects a, Effects b, List<String> lines)
	{
		if (a.rootChance == 0 && b.rootChance > 0)
		{
			lines.add((b.rootChance >= 1 ? "Every hit binds" : percent(b.rootChance) + " chance to bind") + " for " + number(b.rootSeconds) + "s");
			return;
		}
		if (b.rootChance != a.rootChance)
		{
			lines.add("Bind chance " + percent(a.rootChance) + TO + percent(b.rootChance));
		}
		if (b.rootSeconds != a.rootSeconds)
		{
			lines.add("Binds last " + number(a.rootSeconds) + "s" + TO + number(b.rootSeconds) + "s");
		}
	}

	private static void aura(Effects a, Effects b, List<String> lines)
	{
		if (b.auraSpeedPercent != a.auraSpeedPercent)
		{
			lines.add("Allies within " + tiles(b.auraRadius) + ": +" + percent(b.auraSpeedPercent) + " attack speed");
		}
		if (b.auraDamagePercent != a.auraDamagePercent)
		{
			lines.add("Allies within " + tiles(b.auraRadius) + ": +" + percent(b.auraDamagePercent) + " damage");
		}
	}

	private static String tiles(double value)
	{
		return number(value) + (value == 1 ? " tile" : " tiles");
	}

	private static String percent(double fraction)
	{
		return Math.round(fraction * 100) + "%";
	}

	/** Up to two decimal places, without trailing zeros. */
	private static String number(double value)
	{
		String s = String.format(Locale.ROOT, "%.2f", value);
		return s.replaceAll("\\.?0+$", "");
	}

	private static String ordinal(int n)
	{
		return n == 2 ? "2nd" : n == 3 ? "3rd" : n + "th";
	}
}

package com.runedefence.ui;

import com.runedefence.engine.GameEngine;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/** The gold, health, wave and level strip above the battlefield. */
final class HudBar extends JComponent
{
	private final GameEngine engine;
	private final SpriteAtlas atlas;
	private int level = 1;

	HudBar(GameEngine engine, SpriteAtlas atlas)
	{
		this.engine = engine;
		this.atlas = atlas;
		setPreferredSize(new Dimension(224, 22));
		setToolTipText("Match gold, keep health, wave and your RuneDefence level");
	}

	void setLevel(int value)
	{
		level = value;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		Theme.slab(g, 0, 0, getWidth(), getHeight(), Theme.STONE);
		g.setFont(Theme.small());
		boolean match = engine.map() != null;
		int y = 15;
		int inset = (getWidth() - 224) / 2;
		g.drawImage(atlas.frame("coin", 0), inset + 3, 4, null);
		Theme.text(g, match ? Integer.toString(engine.gold()) : "-", inset + 18, y, Theme.YELLOW);
		g.drawImage(atlas.frame("heart", 0), inset + 58, 4, null);
		Theme.text(g, match ? Integer.toString(engine.baseHealth()) : "-", inset + 73, y, Theme.TEXT);
		String wave = match ? "Wave " + Math.min(engine.waveIndex() + 1, engine.waveCount()) + "/" + engine.waveCount() : "Wave -";
		Theme.text(g, wave, inset + 97, y, Theme.TEXT);
		String lv = "Lv " + level;
		Theme.text(g, lv, inset + 221 - g.getFontMetrics().stringWidth(lv), y, Theme.ORANGE);
	}
}

package com.runedefence.ui;

import com.runedefence.model.Content;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.MapDefinition;
import com.runedefence.model.Progression;
import com.runedefence.model.Records;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.text.NumberFormat;
import java.util.Locale;
import javax.swing.JComponent;

/** Permanent level and XP, next unlock, personal bests and recent matches, as a column of cards. */
final class ProgressView extends JComponent
{
	private static final int WIDTH = 224;
	private static final int MARGIN = 3;
	private static final int PAD = 8;
	private static final int CARD_GAP = 4;
	private static final int ROW = 15;
	private static final int ICON = 32;

	private static final int HEADING_HEIGHT = 22;
	private static final int LEVEL_CARD_HEIGHT = 114;
	private static final int UNLOCK_CARD_HEIGHT = 44;
	private static final int MAP_CARD_HEIGHT = 50;
	private static final int EMPTY_CARD_HEIGHT = 24;
	private static final int MATCH_ROW_HEIGHT = 18;
	private static final int BAR_HEIGHT = 14;
	private static final int WAVE_BAR_HEIGHT = 6;

	private final Content content;
	private final SpriteAtlas atlas;
	private Progression progress = new Progression(0, 0);
	private Records records = new Records();

	ProgressView(Content content, SpriteAtlas atlas)
	{
		this.content = content;
		this.atlas = atlas;
		resize();
	}

	void setProgress(Progression value)
	{
		progress = value;
		repaint();
	}

	void setRecords(Records value)
	{
		records = value;
		resize();
		repaint();
	}

	private int mapsPlayed()
	{
		int played = 0;
		for (MapDefinition m : content.maps)
		{
			played += records.maps.containsKey(m.id) ? 1 : 0;
		}
		return played;
	}

	/** Adds up the same pieces the painting walks down, so the scroll area always fits them. */
	int contentHeight()
	{
		int played = mapsPlayed();
		int bests = played == 0 ? EMPTY_CARD_HEIGHT : played * (MAP_CARD_HEIGHT + CARD_GAP) - CARD_GAP;
		int recent = records.history.isEmpty() ? EMPTY_CARD_HEIGHT : records.history.size() * MATCH_ROW_HEIGHT + 2;
		return MARGIN + LEVEL_CARD_HEIGHT + CARD_GAP + UNLOCK_CARD_HEIGHT + HEADING_HEIGHT + bests + HEADING_HEIGHT + recent + MARGIN * 2;
	}

	private void resize()
	{
		setPreferredSize(new Dimension(WIDTH, contentHeight()));
		revalidate();
	}

	private static String fmt(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.UK).format(n);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		g.setColor(Theme.STONE_DARK);
		g.fillRect(0, 0, getWidth(), getHeight());
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		int x = MARGIN;
		int w = getWidth() - MARGIN * 2;
		int y = MARGIN;
		y = paintLevelCard(g, x, y, w) + CARD_GAP;
		y = paintUnlockCard(g, x, y, w);
		y = paintHeading(g, "Personal bests", x, y);
		y = paintBests(g, x, y, w);
		y = paintHeading(g, "Recent matches", x, y);
		paintRecent(g, x, y, w);
	}

	private int paintLevelCard(Graphics2D g, int x, int y, int w)
	{
		Theme.slab(g, x, y, w, LEVEL_CARD_HEIGHT, Theme.STONE);
		int left = x + PAD;
		int right = x + w - PAD;
		int level = progress.level();
		long xp = progress.runeDefenceXp();

		g.setFont(Theme.bold());
		Theme.text(g, "Level " + level, left, y + 18, Theme.ORANGE);
		g.setFont(Theme.small());
		rightAligned(g, fmt(xp) + " XP", right, y + 18, Theme.TEXT);

		int barY = y + 24;
		int barWidth = w - PAD * 2;
		double done = progress.levelProgress();
		g.setColor(Theme.STONE_EDGE);
		g.fillRect(left, barY, barWidth, BAR_HEIGHT);
		g.setColor(Theme.STONE_DARK);
		g.fillRect(left + 1, barY + 1, barWidth - 2, BAR_HEIGHT - 2);
		g.setColor(Theme.XP_FILL);
		g.fillRect(left + 1, barY + 1, (int) ((barWidth - 2) * done), BAR_HEIGHT - 2);
		String percent = level >= Progression.MAX_LEVEL ? "Max level" : (int) (done * 100) + "%";
		Theme.centered(g, percent, left + barWidth / 2, barY + BAR_HEIGHT - 3, Theme.TEXT);

		int line = barY + BAR_HEIGHT + 15;
		if (level < Progression.MAX_LEVEL)
		{
			Theme.text(g, fmt(Progression.xpForLevel(level + 1) - xp) + " XP to level " + (level + 1), left, line, Theme.TEXT);
		}
		else
		{
			Theme.text(g, "You've reached the top level!", left, line, Theme.TEXT);
		}

		line += ROW + 3;
		row(g, "OSRS XP counted", fmt(progress.eligibleOsrsXp), left, right, line, Theme.TEXT);
		line += ROW;
		row(g, "This session", "+" + fmt(progress.sessionOsrsXp), left, right, line, progress.sessionOsrsXp > 0 ? Theme.GREEN : Theme.TEXT);
		line += ROW;
		Theme.text(g, progress.xpRate + " OSRS XP = 1 RuneDefence XP", left, line, Theme.TEXT_MUTED);
		return y + LEVEL_CARD_HEIGHT;
	}

	private int paintUnlockCard(Graphics2D g, int x, int y, int w)
	{
		Theme.slab(g, x, y, w, UNLOCK_CARD_HEIGHT, Theme.STONE);
		int level = progress.level();
		DefenderDefinition next = content.nextUnlock(level);
		g.setFont(Theme.small());
		if (next == null)
		{
			Theme.text(g, "Whole roster unlocked!", x + PAD, y + 26, Theme.GREEN);
			return y + UNLOCK_CARD_HEIGHT;
		}
		g.drawImage(atlas.frame(next.id, 0), x + 6, y + 6, ICON, ICON, null);
		int text = x + 6 + ICON + 6;
		Theme.text(g, "Next unlock", text, y + 13, Theme.TEXT_MUTED);
		Theme.text(g, fit(g, next.name, x + w - PAD - text), text, y + 27, Theme.ORANGE);
		int levels = next.requiredLevel - level;
		Theme.text(g, "Level " + next.requiredLevel + " (" + levels + (levels == 1 ? " level" : " levels") + " to go)", text, y + 40, Theme.TEXT);
		return y + UNLOCK_CARD_HEIGHT;
	}

	private static int paintHeading(Graphics2D g, String title, int x, int y)
	{
		g.setFont(Theme.bold());
		Theme.text(g, title, x + 2, y + 18, Theme.ORANGE);
		g.setFont(Theme.small());
		return y + HEADING_HEIGHT;
	}

	private int paintBests(Graphics2D g, int x, int y, int w)
	{
		if (mapsPlayed() == 0)
		{
			paintEmpty(g, "No matches finished yet.", x, y, w);
			return y + EMPTY_CARD_HEIGHT;
		}
		for (MapDefinition m : content.maps)
		{
			Records.MapBest best = records.maps.get(m.id);
			if (best != null)
			{
				paintMapCard(g, m, best, x, y, w);
				y += MAP_CARD_HEIGHT + CARD_GAP;
			}
		}
		return y - CARD_GAP;
	}

	private void paintMapCard(Graphics2D g, MapDefinition m, Records.MapBest best, int x, int y, int w)
	{
		Theme.slab(g, x, y, w, MAP_CARD_HEIGHT, Theme.STONE);
		int left = x + PAD;
		int right = x + w - PAD;
		boolean cleared = best.bestWave >= m.waves.length;

		Theme.text(g, m.name, left, y + 14, Theme.TEXT);
		rightAligned(g, "Wave " + best.bestWave + "/" + m.waves.length, right, y + 14, cleared ? Theme.GREEN : Theme.YELLOW);

		int barY = y + 19;
		int barWidth = right - left;
		g.setColor(Theme.STONE_EDGE);
		g.fillRect(left, barY, barWidth, WAVE_BAR_HEIGHT);
		g.setColor(cleared ? Theme.GREEN.darker() : Theme.WAVE_FILL);
		g.fillRect(left + 1, barY + 1, (barWidth - 2) * Math.min(best.bestWave, m.waves.length) / m.waves.length, WAVE_BAR_HEIGHT - 2);

		Theme.text(g, "Score " + fmt(best.bestScore), left, y + 41, Theme.TEXT_MUTED);
		rightAligned(g, best.wins + " of " + best.matches + " won", right, y + 41, best.wins > 0 ? Theme.GREEN : Theme.TEXT_MUTED);
	}

	private void paintRecent(Graphics2D g, int x, int y, int w)
	{
		if (records.history.isEmpty())
		{
			paintEmpty(g, "None yet.", x, y, w);
			return;
		}
		Theme.slab(g, x, y, w, records.history.size() * MATCH_ROW_HEIGHT + 2, Theme.STONE);
		int rowY = y + 1;
		boolean shaded = false;
		for (Records.MatchResult r : records.history)
		{
			if (shaded)
			{
				g.setColor(Theme.STONE_MID);
				g.fillRect(x + 2, rowY, w - 4, MATCH_ROW_HEIGHT);
			}
			shaded = !shaded;
			paintMatch(g, r, x, rowY, w);
			rowY += MATCH_ROW_HEIGHT;
		}
	}

	/** Result, then map, then wave reached, then score, in columns that line up down the card. */
	private void paintMatch(Graphics2D g, Records.MatchResult r, int x, int y, int w)
	{
		g.setColor(r.victory ? Theme.GREEN : Theme.RED);
		g.fillRect(x + 3, y + 3, 3, MATCH_ROW_HEIGHT - 6);
		int base = y + 13;
		Theme.text(g, r.victory ? "Won" : "Lost", x + 9, base, r.victory ? Theme.GREEN : Theme.RED);
		String score = fmt(r.score);
		String wave = "W" + r.wave;
		int right = x + w - 5;
		int scoreLeft = right - g.getFontMetrics().stringWidth(score);
		int waveRight = right - 42;
		rightAligned(g, wave, waveRight, base, Theme.TEXT);
		Theme.text(g, score, scoreLeft, base, Theme.YELLOW);
		MapDefinition m = content.map(r.mapId);
		if (m != null)
		{
			int mapLeft = x + 34;
			int room = waveRight - g.getFontMetrics().stringWidth(wave) - 4 - mapLeft;
			Theme.text(g, fit(g, m.name, room), mapLeft, base, Theme.TEXT_MUTED);
		}
	}

	private static void paintEmpty(Graphics2D g, String message, int x, int y, int w)
	{
		Theme.slab(g, x, y, w, EMPTY_CARD_HEIGHT, Theme.STONE);
		Theme.text(g, message, x + PAD, y + 16, Theme.TEXT_MUTED);
	}

	private static void row(Graphics2D g, String label, String value, int left, int right, int y, Color valueColour)
	{
		Theme.text(g, label, left, y, Theme.TEXT_MUTED);
		rightAligned(g, value, right, y, valueColour);
	}

	private static void rightAligned(Graphics2D g, String s, int right, int y, Color c)
	{
		Theme.text(g, s, right - g.getFontMetrics().stringWidth(s), y, c);
	}

	/** Shortens text that wouldn't fit, rather than letting it run into the next column. */
	private static String fit(Graphics2D g, String s, int width)
	{
		if (g.getFontMetrics().stringWidth(s) <= width)
		{
			return s;
		}
		String cut = s;
		while (!cut.isEmpty() && g.getFontMetrics().stringWidth(cut + "..") > width)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut.trim() + "..";
	}
}

package com.runedefence.ui;

import com.runedefence.model.Content;
import com.runedefence.model.DefenderDefinition;
import com.runedefence.model.Progression;
import com.runedefence.model.UpgradeDefinition;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

/**
 * Every defender. An unlocked one opens a page giving every upgrade and exactly what it
 * changes. A locked one shows only its name and the level that unlocks it, and can't be opened.
 */
final class RosterView extends JComponent
{
	private static final int WIDTH = 224;
	private static final int HEADER = 48;
	private static final int ROW = 46;
	private static final int ICON = 28;
	private static final int PAGE_TOP = 26;
	private static final int PAGE_ICON = 42;
	private static final int LINE_HEIGHT = 14;
	/** Text wraps to this whatever the panel's width, so that a scrollbar can't change the page's height. */
	private static final int TEXT_WIDTH = 206;
	private static final int TEXT_X = 8;
	private static final int INDENT = 8;

	/** One line of a defender's page, already wrapped to fit. */
	private static final class Line
	{
		final String text;
		final Color colour;
		final int x;
		final int gapBefore;

		Line(String text, Color colour, int x, int gapBefore)
		{
			this.text = text;
			this.colour = colour;
			this.x = x;
			this.gapBefore = gapBefore;
		}
	}

	private final Content content;
	private final SpriteAtlas atlas;
	private final StoneButton back = new StoneButton("< Roster");
	private final List<Line> page = new ArrayList<>();
	private Progression progress = new Progression(0, 0);
	private DefenderDefinition open;
	private int hoverRow = -1;
	private int listScroll;

	RosterView(Content content, SpriteAtlas atlas)
	{
		this.content = content;
		this.atlas = atlas;
		setLayout(null);
		back.setVisible(false);
		back.setToolTipText("Back to the whole roster");
		back.addActionListener(e -> close());
		add(back);
		setToolTipText("");
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int row = rowAt(e.getY());
				if (open == null && row >= 0)
				{
					open(content.defenders[row]);
				}
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				int row = rowAt(e.getY());
				setHoverRow(row >= 0 && !isLocked(content.defenders[row]) ? row : -1);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHoverRow(-1);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
		resize();
	}

	void setProgress(Progression value)
	{
		progress = value;
		if (open != null && isLocked(open))
		{
			// Swapping account or changing the XP rate can lower the level while a page is open.
			close();
		}
		repaint();
	}

	void open(DefenderDefinition d)
	{
		if (isLocked(d))
		{
			return;
		}
		listScroll = getVisibleRect().y;
		open = d;
		hoverRow = -1;
		setCursor(Cursor.getDefaultCursor());
		back.setVisible(true);
		buildPage();
		resize();
		scrollTo(0);
		repaint();
	}

	void close()
	{
		open = null;
		back.setVisible(false);
		page.clear();
		resize();
		scrollTo(listScroll);
		repaint();
	}

	boolean isShowingPage()
	{
		return open != null;
	}

	/** The words on the open page. */
	String pageText()
	{
		StringBuilder s = new StringBuilder();
		for (Line line : page)
		{
			s.append(line.text).append('\n');
		}
		return s.toString();
	}

	private boolean isLocked(DefenderDefinition d)
	{
		return progress.level() < d.requiredLevel;
	}

	private int rowAt(int y)
	{
		if (open != null || y < HEADER)
		{
			return -1;
		}
		int row = (y - HEADER) / ROW;
		return row < content.defenders.length ? row : -1;
	}

	private void setHoverRow(int row)
	{
		if (row != hoverRow)
		{
			hoverRow = row;
			setCursor(row >= 0 ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : Cursor.getDefaultCursor());
			repaint();
		}
	}

	private void resize()
	{
		int height = open == null ? HEADER + ROW * content.defenders.length + 4 : pageHeight();
		setPreferredSize(new Dimension(WIDTH, height));
		revalidate();
	}

	private void scrollTo(int y)
	{
		// After the revalidate above has taken effect, or the old height would limit the scroll.
		SwingUtilities.invokeLater(() -> scrollRectToVisible(new Rectangle(0, y, 1, getVisibleRect().height)));
	}

	@Override
	public void doLayout()
	{
		back.setBounds(2, 2, 66, 20);
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int row = rowAt(e.getY());
		if (row < 0)
		{
			return null;
		}
		DefenderDefinition d = content.defenders[row];
		return isLocked(d) ? "Reach level " + d.requiredLevel + " to unlock." : "Click for stats and upgrades.";
	}

	// ---- A defender's page --------------------------------------------------

	private void buildPage()
	{
		page.clear();
		DefenderDefinition d = open;
		// The icon and name are painted separately, beside this text.
		wrap(d.description, Theme.TEXT, 0, 0);
		heading("Base stats");
		wrap("Costs " + d.cost + "g, takes " + footprint(d) + ".", Theme.YELLOW, 0, 0);
		for (String stat : DefenderText.baseStats(d))
		{
			wrap(stat, Theme.TEXT, 0, 0);
		}
		buildPath(d, 0, "Path A");
		buildPath(d, 1, "Path B");
		heading("How upgrades work");
		wrap("You can buy the first upgrade on both paths, but only one path can go on to its second.", Theme.TEXT, 0, 0);
		if (DefenderText.canBind(d))
		{
			heading("How binding works");
			wrap("A bound enemy stops walking. It can't be bound again until it has walked for as long as it was held, and bosses can't be bound at all.", Theme.TEXT, 0, 0);
		}
	}

	private void buildPath(DefenderDefinition d, int path, String title)
	{
		UpgradeDefinition[] upgrades = d.path(path);
		int total = 0;
		for (UpgradeDefinition u : upgrades)
		{
			total += u.cost;
		}
		heading(title + " (" + total + "g in all)");
		for (int tier = 0; tier < upgrades.length; tier++)
		{
			UpgradeDefinition u = upgrades[tier];
			wrap((tier + 1) + ". " + u.name + " (" + u.cost + "g)", Theme.YELLOW, 0, tier == 0 ? 0 : 3);
			wrap(u.description, Theme.TEXT_MUTED, INDENT, 0);
			for (String effect : DefenderText.upgradeEffects(d, path == 0 ? tier : 0, path == 1 ? tier : 0, path))
			{
				wrap(effect, Theme.GREEN, INDENT, 0);
			}
		}
	}

	private static String footprint(DefenderDefinition d)
	{
		return d.size == 1 ? "1 tile" : d.size + "x" + d.size + " tiles";
	}

	private void heading(String text)
	{
		page.add(new Line(text, Theme.ORANGE, TEXT_X, 8));
	}

	private void wrap(String text, Color colour, int indent, int gapBefore)
	{
		FontMetrics metrics = getFontMetrics(Theme.small());
		int width = TEXT_WIDTH - indent;
		StringBuilder line = new StringBuilder();
		int gap = gapBefore;
		for (String word : text.split(" "))
		{
			if (line.length() > 0 && metrics.stringWidth(line + " " + word) > width)
			{
				page.add(new Line(line.toString(), colour, TEXT_X + indent, gap));
				line.setLength(0);
				gap = 0;
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}
		page.add(new Line(line.toString(), colour, TEXT_X + indent, gap));
	}

	private int pageHeight()
	{
		int y = pageTextTop();
		for (Line line : page)
		{
			y += line.gapBefore + LINE_HEIGHT;
		}
		return y + 8;
	}

	private static int pageTextTop()
	{
		return PAGE_TOP + PAGE_ICON + 4;
	}

	// ---- Painting -----------------------------------------------------------

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		g.setColor(Theme.STONE_DARK);
		g.fillRect(0, 0, getWidth(), getHeight());
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.setFont(Theme.small());
		if (open == null)
		{
			paintHeader(g);
			paintRows(g);
		}
		else
		{
			paintPage(g);
		}
	}

	private void paintHeader(Graphics2D g)
	{
		int level = progress.level();
		int unlocked = 0;
		for (DefenderDefinition d : content.defenders)
		{
			unlocked += level >= d.requiredLevel ? 1 : 0;
		}
		Theme.text(g, "Unlocked " + unlocked + " of " + content.defenders.length, TEXT_X, 13, Theme.ORANGE);
		DefenderDefinition next = content.nextUnlock(level);
		Theme.text(g, next == null ? "Whole roster unlocked!" : "Next: " + next.name + " at level " + next.requiredLevel, TEXT_X, 28, Theme.TEXT);
		Theme.text(g, "Click an unlocked one for its upgrades.", TEXT_X, 43, Theme.TEXT_MUTED);
	}

	private void paintRows(Graphics2D g)
	{
		for (int i = 0; i < content.defenders.length; i++)
		{
			DefenderDefinition d = content.defenders[i];
			int y = HEADER + i * ROW;
			boolean locked = isLocked(d);
			if (locked)
			{
				paintLockedRow(g, d, y);
				continue;
			}
			Theme.slab(g, 2, y, getWidth() - 4, ROW - 2, i == hoverRow ? Theme.STONE_MID : Theme.STONE);
			paintIcon(g, d, 6, y + 8, ICON, false);
			Theme.text(g, d.name, 38, y + 14, Theme.ORANGE);
			Theme.text(g, d.role, 38, y + 28, Theme.TEXT);
			String chevron = ">";
			Theme.text(g, chevron, getWidth() - g.getFontMetrics().stringWidth(chevron) - 8, y + 28, Theme.TEXT_DIM);
			if (d.size > 1)
			{
				String footprint = d.size + "x" + d.size;
				Theme.text(g, footprint, getWidth() - g.getFontMetrics().stringWidth(footprint) - 8, y + 14, Theme.TEXT_DIM);
			}
			Theme.text(g, d.cost + "g", 38, y + 41, Theme.YELLOW);
			Theme.text(g, "Unlocked", 76, y + 41, Theme.GREEN);
		}
	}

	/** Darker than an unlocked row, with only what it takes to plan for it. */
	private void paintLockedRow(Graphics2D g, DefenderDefinition d, int y)
	{
		Theme.slab(g, 2, y, getWidth() - 4, ROW - 2, Theme.STONE_DARK);
		paintIcon(g, d, 6, y + 8, ICON, true);
		Theme.text(g, d.name, 38, y + 19, Theme.TEXT_MUTED);
		Theme.text(g, "Unlocks at level " + d.requiredLevel, 38, y + 34, Theme.RED);
	}

	private void paintIcon(Graphics2D g, DefenderDefinition d, int x, int y, int size, boolean locked)
	{
		Composite old = g.getComposite();
		if (locked)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.2f));
		}
		g.drawImage(atlas.frame(d.id, 0), x, y, size, size, null);
		g.setComposite(old);
		if (locked)
		{
			g.drawImage(atlas.frame("lock", 0), x + (size - 13) / 2, y + (size - 13) / 2, null);
		}
	}

	private void paintPage(Graphics2D g)
	{
		paintIcon(g, open, TEXT_X, PAGE_TOP, PAGE_ICON, false);
		Font small = g.getFont();
		g.setFont(Theme.bold());
		int nameX = TEXT_X + PAGE_ICON + 6;
		Theme.text(g, open.name, nameX, PAGE_TOP + 14, Theme.ORANGE);
		g.setFont(small);
		Theme.text(g, open.role, nameX, PAGE_TOP + 28, Theme.TEXT);
		Theme.text(g, "Unlocked at level " + open.requiredLevel, nameX, PAGE_TOP + 41, Theme.GREEN);
		int y = pageTextTop();
		for (Line line : page)
		{
			y += line.gapBefore + LINE_HEIGHT;
			Theme.text(g, line.text, line.x, y - 3, line.colour);
		}
	}
}

package com.runedefence.ui;

import com.runedefence.engine.GameEngine;
import com.runedefence.engine.ScoreCalculator;
import com.runedefence.engine.SimulationClock;
import com.runedefence.model.MapDefinition;
import com.runedefence.model.MatchSave;
import com.runedefence.model.Progression;
import com.runedefence.model.Records;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.Timer;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar. All game and UI state belongs to the Swing EDT: one timer steps the
 * engine and repaints, so the engine can never be mutated while it is being drawn.
 * None of it touches the game's client thread.
 */
public final class RuneDefencePanel extends PluginPanel
{
	public static final int PAUSE_HIDDEN = 1;
	public static final int PAUSE_LOGOUT = 2;
	public static final int PAUSE_FOCUS = 4;

	private static final int ACTIVE_FRAME_MS = 33;
	private static final int HIDDEN_FRAME_MS = 100;
	private static final int ARM_FRAMES = 90;
	private static final int CONTENT_HEIGHT = 472;

	/** What the panel needs from whichever program is hosting it. */
	public interface Host
	{
		void saveMatch(MatchSave save);

		void saveRecords(Records records);

		void tutorialFinished();
	}

	/** Settings, as a plain value so the panel doesn't depend on RuneLite's config proxy. */
	public static final class Settings
	{
		public boolean autoStart;
		public int interWaveDelaySeconds;
		public boolean pauseOnHide;
		public boolean effects;
	}

	private final GameEngine engine;
	private final Host host;
	private final SimulationClock clock = new SimulationClock();
	private final Timer timer;

	private final BattlefieldPanel field;
	private final HudBar hud;
	private final ShopDock shop;
	private final DefenderDock detail;
	private final RosterView roster;
	private final ProgressView progressView;

	private final JPanel dock = new JPanel(new CardLayout());
	private final JPanel cards = new JPanel(new CardLayout());
	private final StoneButton[] tabs = {new StoneButton("Play"), new StoneButton("Roster"), new StoneButton("Progress")};
	private final StoneButton primary = new StoneButton("");
	private final StoneButton pause = new StoneButton("Pause");
	private final StoneButton quit = new StoneButton("Quit");

	private Records records = new Records();
	private int playerLevel = 1;
	private int menuIndex;
	private MatchSave savedMatch;
	private Settings settings = new Settings();
	private int pauseReasons;
	private boolean systemPaused;
	private boolean active;
	private boolean disposed;
	private long lastNanos;
	private int quitArmedFrames;

	private int uiSignature;
	private int saveSignature = Integer.MIN_VALUE;
	private MatchSave lastSaved;
	private boolean showingDetail;

	public RuneDefencePanel(GameEngine engine, SpriteAtlas atlas, Host host)
	{
		super(false);
		this.engine = engine;
		this.host = host;
		engine.setMatchEndListener(this::onMatchEnd);

		field = new BattlefieldPanel(engine, atlas, new BattlefieldPanel.Listener()
		{
			@Override
			public void onFieldChanged()
			{
				refreshUi();
			}

			@Override
			public void onTutorialFinished()
			{
				host.tutorialFinished();
			}
		});
		hud = new HudBar(engine, atlas);
		shop = new ShopDock(engine, atlas, field);
		detail = new DefenderDock(engine, field, this::refreshUi);
		roster = new RosterView(engine.content(), atlas);
		progressView = new ProgressView(engine.content(), atlas);

		setLayout(new BorderLayout());
		setBackground(Theme.STONE_DARK);
		add(buildTabs(), BorderLayout.NORTH);
		cards.add(scroll(buildPlay()), tabs[0].getText());
		cards.add(scroll(roster), tabs[1].getText());
		cards.add(scroll(progressView), tabs[2].getText());
		// Fixed, or the longest tab would stretch the panel. Longer tabs scroll instead.
		cards.setPreferredSize(new Dimension(PANEL_WIDTH, CONTENT_HEIGHT));
		add(cards, BorderLayout.CENTER);
		selectTab(0);

		timer = new Timer(ACTIVE_FRAME_MS, e -> tick());
		timer.setInitialDelay(0);
		refreshUi();
	}

	private JPanel buildTabs()
	{
		JPanel row = new JPanel(new GridLayout(1, tabs.length));
		row.setBackground(Theme.STONE_DARK);
		for (int i = 0; i < tabs.length; i++)
		{
			int index = i;
			tabs[i].addActionListener(e -> selectTab(index));
			row.add(tabs[i]);
		}
		return row;
	}

	void selectTab(int index)
	{
		for (int i = 0; i < tabs.length; i++)
		{
			tabs[i].setActive(i == index);
			tabs[i].setTextColour(i == index ? Theme.ORANGE : Theme.TEXT);
		}
		((CardLayout) cards.getLayout()).show(cards, tabs[index].getText());
	}

	private JPanel buildPlay()
	{
		JPanel play = new JPanel();
		play.setLayout(new BoxLayout(play, BoxLayout.Y_AXIS));
		play.setBackground(Theme.STONE_DARK);

		JPanel fieldRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		fieldRow.setBackground(Theme.STONE_DARK);
		fieldRow.setBorder(BorderFactory.createMatteBorder(1, 0, 1, 0, Theme.STONE_EDGE));
		fieldRow.add(field);

		primary.setTextColour(Theme.YELLOW);
		primary.addActionListener(e -> primaryAction());
		pause.addActionListener(e -> togglePause());
		quit.addActionListener(e -> quitAction());
		JPanel controls = new JPanel(new BorderLayout(1, 0));
		controls.setBackground(Theme.STONE_DARK);
		JPanel right = new JPanel(new GridLayout(1, 2, 1, 0));
		right.setOpaque(false);
		right.add(pause);
		right.add(quit);
		right.setPreferredSize(new Dimension(96, 24));
		controls.add(primary, BorderLayout.CENTER);
		controls.add(right, BorderLayout.EAST);

		dock.setBackground(Theme.STONE_DARK);
		dock.add(shop, "shop");
		dock.add(detail, "detail");
		dock.setPreferredSize(new Dimension(224, 88));

		for (JPanel part : new JPanel[]{fieldRow, controls, dock})
		{
			part.setAlignmentX(LEFT_ALIGNMENT);
		}
		hud.setAlignmentX(LEFT_ALIGNMENT);
		play.add(hud);
		play.add(fieldRow);
		play.add(controls);
		play.add(dock);
		return play;
	}

	private static JScrollPane scroll(java.awt.Component view)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(Theme.STONE_DARK);
		holder.add(view, BorderLayout.NORTH);
		JScrollPane pane = new JScrollPane(holder, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		pane.setBorder(null);
		pane.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return pane;
	}

	// ---- Host-facing API. Call these on the EDT. ----------------------------

	/**
	 * Swaps in another account's data, after the host has saved the previous account's.
	 * With keepMatch, a match in progress carries over, for someone who started playing
	 * at the login screen and has now logged in.
	 */
	public void loadAccount(Progression progress, Records accountRecords, MatchSave saved, boolean keepMatch)
	{
		if (!keepMatch || !engine.isMatchActive())
		{
			engine.abandon();
			field.clearSelection();
		}
		records = accountRecords;
		savedMatch = engine.isMatchActive() ? null : saved;
		if (savedMatch != null)
		{
			selectMap(savedMatch.mapId);
		}
		lastSaved = null;
		saveSignature = Integer.MIN_VALUE;
		progressView.setRecords(records);
		setProgress(progress);
		refreshUi();
	}

	public void setProgress(Progression progress)
	{
		int level = progress.level();
		playerLevel = level;
		engine.setPlayerLevel(level);
		hud.setLevel(level);
		shop.setLevel(level);
		roster.setProgress(progress);
		progressView.setProgress(progress);
		refreshUi();
	}

	public void applySettings(Settings value)
	{
		settings = value;
		engine.setAutoStartDelay(value.autoStart ? value.interWaveDelaySeconds : 0);
		field.setEffects(value.effects);
		if (!value.pauseOnHide)
		{
			setPauseReason(PAUSE_HIDDEN, false);
		}
		refreshUi();
	}

	public void showTutorial()
	{
		field.showTutorial();
	}

	/** Pauses for an outside reason, and resumes once every such reason has cleared. */
	public void setPauseReason(int reason, boolean on)
	{
		pauseReasons = on ? pauseReasons | reason : pauseReasons & ~reason;
		if (pauseReasons != 0)
		{
			if (engine.state() == GameEngine.State.RUNNING || engine.state() == GameEngine.State.WAVE_COMPLETE)
			{
				engine.pause();
				systemPaused = true;
			}
		}
		else if (systemPaused)
		{
			systemPaused = false;
			engine.resume();
		}
		refreshUi();
		updateTimer();
	}

	/** The resume point to store for this account, or null if there is no active match. */
	public MatchSave currentSave()
	{
		return engine.isMatchActive() ? engine.checkpoint() : savedMatch;
	}

	public void dispose()
	{
		disposed = true;
		active = false;
		timer.stop();
		engine.setMatchEndListener(null);
	}

	// ---- Sidebar lifecycle --------------------------------------------------

	@Override
	public void onActivate()
	{
		active = true;
		setPauseReason(PAUSE_HIDDEN, false);
		updateTimer();
	}

	@Override
	public void onDeactivate()
	{
		active = false;
		if (settings.pauseOnHide)
		{
			setPauseReason(PAUSE_HIDDEN, true);
		}
		updateTimer();
	}

	/** Idle costs nothing: the timer only runs if there's something to show or simulate. */
	private void updateTimer()
	{
		boolean simulating = engine.state() == GameEngine.State.RUNNING || engine.state() == GameEngine.State.WAVE_COMPLETE;
		if (!disposed && (active || simulating))
		{
			timer.setDelay(active ? ACTIVE_FRAME_MS : HIDDEN_FRAME_MS);
			if (!timer.isRunning())
			{
				lastNanos = System.nanoTime();
				timer.start();
			}
		}
		else
		{
			timer.stop();
		}
	}

	// ---- Actions ------------------------------------------------------------

	private void primaryAction()
	{
		switch (engine.state())
		{
			case MENU:
				if (savedMatch != null && engine.restore(savedMatch))
				{
					savedMatch = null;
				}
				else
				{
					startNewMatch();
				}
				break;
			case VICTORY:
			case DEFEAT:
				startNewMatch();
				break;
			case PREPARING:
			case WAVE_COMPLETE:
				engine.startWave();
				break;
			default:
				break;
		}
		refreshUi();
		updateTimer();
	}

	private void startNewMatch()
	{
		// After a match, New match replays that map. Otherwise it's whatever the picker shows.
		String mapId = engine.map() != null ? engine.map().id : selectedMap().id;
		selectMap(mapId);
		if (engine.newMatch(mapId, System.nanoTime()) == GameEngine.Result.OK)
		{
			savedMatch = null;
			field.clearSelection();
		}
	}

	private MapDefinition selectedMap()
	{
		return engine.content().maps[menuIndex];
	}

	private void selectMap(String mapId)
	{
		MapDefinition[] maps = engine.content().maps;
		for (int i = 0; i < maps.length; i++)
		{
			if (maps[i].id.equals(mapId))
			{
				menuIndex = i;
				return;
			}
		}
	}

	void changeMap(int delta)
	{
		menuIndex = Math.floorMod(menuIndex + delta, engine.content().maps.length);
		refreshUi();
	}

	private void togglePause()
	{
		if (engine.state() == GameEngine.State.MENU)
		{
			changeMap(-1);
			return;
		}
		if (engine.state() == GameEngine.State.PAUSED)
		{
			systemPaused = false;
			engine.resume();
		}
		else if (engine.pause() == GameEngine.Result.OK)
		{
			systemPaused = false;
		}
		refreshUi();
		updateTimer();
	}

	/** Quit needs a second click, because it throws the match away. */
	private void quitAction()
	{
		if (engine.state() == GameEngine.State.MENU && savedMatch != null)
		{
			// On the menu, this discards a saved match and starts a clean slate.
			if (quitArmedFrames == 0)
			{
				quitArmedFrames = ARM_FRAMES;
				refreshUi();
				return;
			}
			savedMatch = null;
			quitArmedFrames = 0;
			host.saveMatch(null);
			refreshUi();
			return;
		}
		if (engine.state() == GameEngine.State.MENU)
		{
			changeMap(1);
			return;
		}
		boolean finished = !engine.isMatchActive();
		if (!finished && quitArmedFrames == 0)
		{
			quitArmedFrames = ARM_FRAMES;
			refreshUi();
			return;
		}
		quitArmedFrames = 0;
		engine.abandon();
		systemPaused = false;
		field.clearSelection();
		host.saveMatch(null);
		lastSaved = null;
		refreshUi();
		updateTimer();
	}

	private void onMatchEnd(GameEngine e, boolean victory)
	{
		Records.MatchResult r = new Records.MatchResult();
		r.mapId = e.map().id;
		r.victory = victory;
		r.wave = e.wavesCleared();
		r.score = e.score();
		r.scoreVersion = ScoreCalculator.VERSION;
		r.baseHealth = e.baseHealth();
		r.goldSpent = e.goldSpent();
		r.enemiesDefeated = e.enemiesDefeated();
		r.seconds = (int) (e.ticks() * GameEngine.STEP_SECONDS);
		r.difficulty = "normal";
		records.add(r);
		selectMap(r.mapId);
		progressView.setRecords(records);
		host.saveRecords(records);
		host.saveMatch(null);
		lastSaved = null;
	}

	// ---- Frame --------------------------------------------------------------

	void tick()
	{
		long now = System.nanoTime();
		long deltaMs = (now - lastNanos) / 1_000_000;
		lastNanos = now;
		int steps = clock.advance(deltaMs);
		for (int i = 0; i < steps; i++)
		{
			engine.step();
		}
		if (quitArmedFrames > 0 && --quitArmedFrames == 0)
		{
			refreshUi();
		}
		saveIfChanged();
		if (isShowing())
		{
			field.animate(deltaMs / 1000.0, clock.alpha());
			field.repaint();
			refreshIfChanged();
		}
		updateTimer();
	}

	/** Between waves the board is the save, so each change to it is written. Mid-wave nothing changes. */
	private void saveIfChanged()
	{
		if (!engine.isMatchActive())
		{
			return;
		}
		int signature = 31 * engine.gold() + 7 * engine.waveIndex() + engine.state().ordinal() + 1009 * engine.defenders().size();
		if (signature == saveSignature)
		{
			return;
		}
		saveSignature = signature;
		MatchSave save = engine.checkpoint();
		if (save != null && save != lastSaved)
		{
			lastSaved = save;
			host.saveMatch(save);
		}
	}

	private void refreshIfChanged()
	{
		if (uiState() != uiSignature)
		{
			refreshUi();
		}
		hud.repaint();
	}

	/** Changes whenever the buttons or docks need redrawing, which is far less often than every frame. */
	private int uiState()
	{
		return engine.gold() * 31 + engine.baseHealth() * 37 + engine.state().ordinal() * 41 + engine.waveIndex() * 43
			+ (int) Math.ceil(engine.autoStartTimer()) * 47;
	}

	void refreshUi()
	{
		uiSignature = uiState();
		if (field.selected() != null && !engine.defenders().contains(field.selected()))
		{
			field.clearSelection();
			return;
		}
		updateControls();
		boolean wantDetail = field.selected() != null;
		if (wantDetail != showingDetail)
		{
			showingDetail = wantDetail;
			((CardLayout) dock.getLayout()).show(dock, wantDetail ? "detail" : "shop");
		}
		shop.refresh();
		detail.refresh();
		hud.repaint();
		field.repaint();
	}

	private void updateControls()
	{
		GameEngine.State state = engine.state();
		switch (state)
		{
			case MENU:
				boolean locked = savedMatch == null && playerLevel < selectedMap().requiredLevel;
				String label = savedMatch != null ? "Resume wave " + (savedMatch.wave + 1) : locked ? "Level " + selectedMap().requiredLevel + " needed" : "New match";
				primary.setLabel(label, savedMatch != null ? "Carry on from your saved match" : "Start a new match on this map");
				primary.setEnabled(!locked);
				break;
			case PREPARING:
				primary.setLabel("Start wave " + (engine.waveIndex() + 1), "Send the next wave");
				primary.setEnabled(true);
				break;
			case WAVE_COMPLETE:
				int left = (int) Math.ceil(engine.autoStartTimer());
				primary.setLabel(left > 0 ? "Next wave (" + left + "s)" : "Start wave " + (engine.waveIndex() + 1), "Send the next wave now");
				primary.setEnabled(true);
				break;
			case RUNNING:
				primary.setLabel("Wave in progress", null);
				primary.setEnabled(false);
				break;
			case PAUSED:
				primary.setLabel("Paused", null);
				primary.setEnabled(false);
				break;
			default:
				primary.setLabel("New match", "Start again on this map");
				primary.setEnabled(true);
				break;
		}
		boolean menu = state == GameEngine.State.MENU;
		boolean canPause = state == GameEngine.State.RUNNING || state == GameEngine.State.WAVE_COMPLETE
			|| state == GameEngine.State.PREPARING || state == GameEngine.State.PAUSED;
		// On the menu these two become the map picker, unless a saved match has to be dealt with first.
		boolean menuWithSave = menu && savedMatch != null;
		pause.setEnabled(canPause || (menu && !menuWithSave));
		if (menu)
		{
			pause.setLabel("< Map", "Previous map");
		}
		else
		{
			pause.setLabel(state == GameEngine.State.PAUSED ? "Resume" : "Pause", "Freeze or resume the match");
		}
		quit.setEnabled(true);
		String quitLabel = menuWithSave ? "Discard" : menu ? "Map >" : engine.isMatchActive() ? "Quit" : "Menu";
		String quitTip = menuWithSave ? "Delete your saved match" : menu ? "Next map" : "Leave this match. Progress is safe.";
		quit.setLabel(quitArmedFrames > 0 ? "Sure?" : quitLabel, quitTip);
		field.setMenu(selectedMap(), savedMatch == null && playerLevel < selectedMap().requiredLevel, records.maps.get(selectedMap().id));
		quit.setTextColour(quitArmedFrames > 0 ? Theme.RED : Theme.TEXT);
	}

	BattlefieldPanel field()
	{
		return field;
	}

	ShopDock shop()
	{
		return shop;
	}
}

package com.runedefence.ui;

import com.runedefence.engine.GameEngine;
import com.runedefence.model.DefenderDefinition;
import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;

/** Pages of defenders to buy, each page a row that stays readable in a narrow sidebar. */
final class ShopDock extends JPanel
{
	static final int PER_PAGE = 5;

	private static final int ICON = 28;
	private static final int ARROW_WIDTH = 22;
	private static final int ARROW_HEIGHT = 18;

	private final GameEngine engine;
	private final SpriteAtlas atlas;
	private final BattlefieldPanel field;
	private final DefenderDefinition[] roster;
	private final ShopButton[] buttons = new ShopButton[PER_PAGE];
	private final Hint hint = new Hint();
	private int level = 1;
	private int page;

	ShopDock(GameEngine engine, SpriteAtlas atlas, BattlefieldPanel field)
	{
		super(new BorderLayout());
		this.engine = engine;
		this.atlas = atlas;
		this.field = field;
		this.roster = engine.content().defenders;
		setBackground(Theme.STONE_DARK);
		JPanel row = new JPanel(new GridLayout(1, PER_PAGE, 1, 0));
		row.setOpaque(false);
		for (int i = 0; i < PER_PAGE; i++)
		{
			buttons[i] = new ShopButton();
			row.add(buttons[i]);
		}
		add(row, BorderLayout.CENTER);
		add(hint, BorderLayout.SOUTH);
		showPage(0);
	}

	void setLevel(int value)
	{
		level = value;
	}

	int pageCount()
	{
		return (roster.length + PER_PAGE - 1) / PER_PAGE;
	}

	void showPage(int index)
	{
		page = Math.floorMod(index, pageCount());
		for (int i = 0; i < PER_PAGE; i++)
		{
			int slot = page * PER_PAGE + i;
			buttons[i].setDefender(slot < roster.length ? roster[slot] : null);
		}
		refresh();
	}

	void refresh()
	{
		for (ShopButton b : buttons)
		{
			b.update();
		}
		hint.repaint();
	}

	private final class ShopButton extends JButton
	{
		private DefenderDefinition def;

		ShopButton()
		{
			setFocusable(false);
			setBorderPainted(false);
			setContentAreaFilled(false);
			setFocusPainted(false);
			setMargin(new Insets(0, 0, 0, 0));
			addActionListener(e -> choose());
		}

		void setDefender(DefenderDefinition value)
		{
			def = value;
			setEnabled(def != null);
			getAccessibleContext().setAccessibleName(def == null ? "Empty" : def.name + ", costs " + def.cost + " gold");
		}

		private void choose()
		{
			if (def == null || level < def.requiredLevel || !engine.isMatchActive())
			{
				return;
			}
			if (field.placing() == def)
			{
				field.clearSelection();
			}
			else if (engine.gold() >= def.cost)
			{
				field.setPlacing(def);
			}
		}

		void update()
		{
			String tip = null;
			if (def != null)
			{
				String footprint = def.size > 1 ? " Takes " + def.size + "x" + def.size + " tiles." : "";
				if (level < def.requiredLevel)
				{
					tip = def.name + " is locked: needs RuneDefence level " + def.requiredLevel;
				}
				else if (engine.isMatchActive() && engine.gold() < def.cost)
				{
					tip = def.name + ": costs " + def.cost + " gold, you have " + engine.gold();
				}
				else
				{
					tip = def.name + " (" + def.role + "): " + def.description + footprint;
				}
			}
			setToolTipText(tip);
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics;
			if (def == null)
			{
				Theme.slab(g, 0, 0, getWidth(), getHeight(), Theme.STONE_DARK);
				return;
			}
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			boolean locked = level < def.requiredLevel;
			boolean afford = !engine.isMatchActive() || engine.gold() >= def.cost;
			boolean chosen = field.placing() == def;
			boolean hover = getModel().isRollover() && !locked;
			Theme.slab(g, 0, 0, getWidth(), getHeight(), chosen ? Theme.STONE_LIGHT : hover ? Theme.STONE_MID : Theme.STONE);
			Composite old = g.getComposite();
			if (locked || !afford)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, locked ? 0.3f : 0.55f));
			}
			// Big defenders shrink to fit, so that every icon stays inside its own button.
			g.drawImage(atlas.frame(def.id, 0), (getWidth() - ICON) / 2, 2, ICON, ICON, null);
			g.setComposite(old);
			g.setFont(Theme.small());
			int y = getHeight() - 5;
			if (locked)
			{
				g.drawImage(atlas.frame("lock", 0), (getWidth() - 13) / 2, 10, null);
				Theme.centered(g, "Lv " + def.requiredLevel, getWidth() / 2, y, Theme.ORANGE);
			}
			else
			{
				Theme.centered(g, def.cost + "g", getWidth() / 2, y, afford ? Theme.YELLOW : Theme.RED);
			}
		}
	}

	/** Two lines of help on the left, with the page arrows and number on the right. */
	private final class Hint extends JComponent
	{
		private final StoneButton previous = new StoneButton("<");
		private final StoneButton next = new StoneButton(">");

		Hint()
		{
			setPreferredSize(new Dimension(224, 34));
			previous.setLabel("<", "Previous page of defenders");
			next.setLabel(">", "Next page of defenders");
			previous.addActionListener(e -> showPage(page - 1));
			next.addActionListener(e -> showPage(page + 1));
			add(previous);
			add(next);
		}

		@Override
		public void doLayout()
		{
			int x = getWidth() - ARROW_WIDTH * 2 - 2;
			previous.setBounds(x, 1, ARROW_WIDTH, ARROW_HEIGHT);
			next.setBounds(x + ARROW_WIDTH, 1, ARROW_WIDTH, ARROW_HEIGHT);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics;
			g.setFont(Theme.small());
			Theme.centered(g, (page + 1) + "/" + pageCount(), getWidth() - ARROW_WIDTH - 2, 31, Theme.TEXT_DIM);
			DefenderDefinition placing = field.placing();
			if (placing != null)
			{
				Theme.text(g, placing.name, 4, 13, Theme.ORANGE);
				String size = placing.size > 1 ? " (" + placing.size + "x" + placing.size + ")" : "";
				Theme.text(g, "Click a tile" + size + ".", 4, 28, Theme.TEXT);
			}
			else if (!engine.isMatchActive())
			{
				Theme.text(g, "Start a match to recruit.", 4, 13, Theme.TEXT_DIM);
			}
			else
			{
				Theme.text(g, "Recruit above, or click", 4, 13, Theme.TEXT);
				Theme.text(g, "a defender to upgrade.", 4, 28, Theme.TEXT);
			}
		}
	}
}

package com.runedefence.ui;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.util.ImageUtil;

/** Every sprite lives on one of a few small sheets, decoded once at startup and shared. */
public final class SpriteAtlas
{
	public static final class Sprite
	{
		public final BufferedImage[] frames;
		public final int width;
		public final int height;

		Sprite(BufferedImage[] frames)
		{
			this.frames = frames;
			this.width = frames[0].getWidth();
			this.height = frames[0].getHeight();
		}
	}

	private final Map<String, Sprite> sprites = new HashMap<>();

	public SpriteAtlas(Gson gson) throws IOException
	{
		try (InputStream in = SpriteAtlas.class.getResourceAsStream("/com/runedefence/sprites.json"))
		{
			if (in == null)
			{
				throw new IOException("Missing sprite index");
			}
			JsonObject index = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class);
			for (Map.Entry<String, JsonElement> sheet : index.entrySet())
			{
				loadSheet(sheet.getKey(), sheet.getValue().getAsJsonObject());
			}
		}
	}

	private void loadSheet(String name, JsonObject sheetIndex)
	{
		BufferedImage source = ImageUtil.loadImageResource(SpriteAtlas.class, "/com/runedefence/sprites/" + name + ".png");
		// The file is indexed to keep it small, but ARGB is what draws quickly.
		BufferedImage sheet = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		g.drawImage(source, 0, 0, null);
		g.dispose();

		for (Map.Entry<String, JsonElement> entry : sheetIndex.entrySet())
		{
			JsonArray a = entry.getValue().getAsJsonArray();
			int x = a.get(0).getAsInt();
			int y = a.get(1).getAsInt();
			int w = a.get(2).getAsInt();
			int h = a.get(3).getAsInt();
			BufferedImage[] frames = new BufferedImage[a.get(4).getAsInt()];
			for (int f = 0; f < frames.length; f++)
			{
				frames[f] = sheet.getSubimage(x + f * w, y, w, h);
			}
			sprites.put(entry.getKey(), new Sprite(frames));
		}
	}

	public Sprite get(String name)
	{
		return sprites.get(name);
	}

	public BufferedImage frame(String name, int index)
	{
		Sprite s = sprites.get(name);
		return s.frames[Math.floorMod(index, s.frames.length)];
	}
}

package com.runedefence.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JButton;

/**
 * A chiselled stone button. It never takes keyboard focus, so clicking it leaves
 * the game's own key bindings working.
 */
class StoneButton extends JButton
{
	private Color textColour = Theme.TEXT;
	private boolean active;

	StoneButton(String text)
	{
		super(text);
		setFocusable(false);
		setBorderPainted(false);
		setContentAreaFilled(false);
		setFocusPainted(false);
		setRolloverEnabled(true);
		setFont(Theme.small());
		setPreferredSize(new Dimension(60, 22));
	}

	void setLabel(String text, String tooltip)
	{
		if (!text.equals(getText()))
		{
			setText(text);
			getAccessibleContext().setAccessibleName(text);
		}
		setToolTipText(tooltip);
	}

	void setTextColour(Color c)
	{
		textColour = c;
		repaint();
	}

	void setActive(boolean value)
	{
		if (active != value)
		{
			active = value;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		boolean down = getModel().isArmed() && getModel().isPressed();
		boolean hover = getModel().isRollover() && isEnabled();
		Color face = !isEnabled() ? Theme.STONE_DARK : active || down ? Theme.STONE_LIGHT : hover ? Theme.STONE_MID : Theme.STONE;
		Theme.slab(g, 0, 0, getWidth(), getHeight(), face);
		g.setFont(getFont());
		int y = (getHeight() + g.getFontMetrics().getAscent()) / 2 - 2 + (down ? 1 : 0);
		Theme.centered(g, getText(), getWidth() / 2, y, isEnabled() ? textColour : Theme.TEXT_DIM);
	}
}

package com.runedefence.ui;

import com.runedefence.model.MapDefinition;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Random;

/** Paints a map once into a single image, so that the battlefield only ever blits it. */
final class Terrain
{
	private Terrain()
	{
	}

	private static Color colour(String hex)
	{
		return new Color(Integer.parseInt(hex, 16));
	}

	private static Color[] colours(String[] hex)
	{
		Color[] out = new Color[hex.length];
		for (int i = 0; i < hex.length; i++)
		{
			out[i] = colour(hex[i]);
		}
		return out;
	}

	static BufferedImage render(MapDefinition map, SpriteAtlas atlas, int tile)
	{
		int w = map.columns * tile;
		int h = map.rows * tile;
		BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		// Fixed seed: a given map always looks the same.
		Random rng = new Random(map.id.hashCode());

		MapDefinition.Palette p = map.palette;
		Color groundA = colour(p.groundA);
		Color groundB = colour(p.groundB);
		Color[] groundFlecks = colours(p.groundFlecks);
		Color dirt = colour(p.path);
		Color dirtEdge = colour(p.pathEdge);
		Color[] dirtFlecks = colours(p.pathFlecks);

		for (int row = 0; row < map.rows; row++)
		{
			for (int col = 0; col < map.columns; col++)
			{
				int x = col * tile;
				int y = row * tile;
				boolean path = map.isOnPath(col, row);
				// A faint checker lets players read the grid without drawn lines.
				g.setColor(path ? dirt : (col + row) % 2 == 0 ? groundA : groundB);
				g.fillRect(x, y, tile, tile);
				flecks(g, rng, x, y, tile, path ? dirtFlecks : groundFlecks, path ? 14 : 10);
				if (path)
				{
					pathEdges(g, map, col, row, x, y, tile, dirtEdge);
				}
				else if (map.flowers && map.tiles[row].charAt(col) == '.' && rng.nextInt(9) == 0)
				{
					g.drawImage(atlas.frame("flower", 0), x, y, tile, tile, null);
				}
			}
		}

		// Scenery runs top to bottom so that nearer objects overlap further ones.
		int keepCol = -1;
		int keepRow = -1;
		for (int row = 0; row < map.rows; row++)
		{
			for (int col = 0; col < map.columns; col++)
			{
				char letter = map.tiles[row].charAt(col);
				if (letter == 'K')
				{
					if (keepCol < 0)
					{
						keepCol = col;
						keepRow = row;
					}
				}
				else if (letter != '.')
				{
					drawScenery(g, atlas, map, letter, col * tile, row * tile, tile);
				}
			}
		}
		if (keepCol >= 0)
		{
			SpriteAtlas.Sprite keep = atlas.get(map.sceneryFor('K', "keep"));
			int kw = keep.width * tile / BattlefieldPanel.NATIVE_TILE;
			int kh = keep.height * tile / BattlefieldPanel.NATIVE_TILE;
			g.drawImage(keep.frames[0], keepCol * tile, (keepRow + 1) * tile - kh, kw, kh, null);
		}
		g.dispose();
		return image;
	}

	private static String defaultScenery(char letter)
	{
		switch (letter)
		{
			case 'T':
				return "tree";
			case 'W':
				return "water";
			case 'C':
				return "camp";
			default:
				return "rock";
		}
	}

	/** Tall scenery stands on the bottom of its tile, and may overlap the tile above. */
	private static void drawScenery(Graphics2D g, SpriteAtlas atlas, MapDefinition map, char letter, int x, int y, int tile)
	{
		SpriteAtlas.Sprite s = atlas.get(map.sceneryFor(letter, defaultScenery(letter)));
		int height = s.height * tile / BattlefieldPanel.NATIVE_TILE;
		g.drawImage(s.frames[0], x, y + tile - height, tile, height, null);
	}

	private static void flecks(Graphics2D g, Random rng, int x, int y, int tile, Color[] colours, int count)
	{
		for (int i = 0; i < count; i++)
		{
			g.setColor(colours[rng.nextInt(colours.length)]);
			g.fillRect(x + rng.nextInt(tile), y + rng.nextInt(tile), 1 + rng.nextInt(2), 1);
		}
	}

	private static void pathEdges(Graphics2D g, MapDefinition map, int col, int row, int x, int y, int tile, Color edge)
	{
		g.setColor(edge);
		if (!map.isOnPath(col, row - 1))
		{
			g.fillRect(x, y, tile, 2);
		}
		if (!map.isOnPath(col, row + 1))
		{
			g.fillRect(x, y + tile - 2, tile, 2);
		}
		if (!map.isOnPath(col - 1, row))
		{
			g.fillRect(x, y, 2, tile);
		}
		if (!map.isOnPath(col + 1, row))
		{
			g.fillRect(x + tile - 2, y, 2, tile);
		}
	}
}

package com.runedefence.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import net.runelite.client.ui.FontManager;

/** The stone-and-parchment look, using RuneLite's bundled pixel fonts. */
final class Theme
{
	static final Color STONE_DARK = new Color(0x25221B);
	static final Color STONE = new Color(0x3B3629);
	static final Color STONE_MID = new Color(0x4C4636);
	static final Color STONE_LIGHT = new Color(0x6B6450);
	static final Color STONE_EDGE = new Color(0x14120D);

	static final Color TEXT = new Color(0xE8DFC0);
	static final Color TEXT_DIM = new Color(0x9A927A);
	/** For secondary text that still has to be read comfortably on a stone slab. */
	static final Color TEXT_MUTED = new Color(0xC4BA9C);
	static final Color YELLOW = new Color(0xFFE040);
	static final Color ORANGE = new Color(0xFF981F);
	static final Color GREEN = new Color(0x40D040);
	static final Color RED = new Color(0xF04030);

	static final Color HP_GREEN = new Color(0x18C818);
	static final Color HP_RED = new Color(0xC81818);
	static final Color SPLAT_RED = new Color(0xB81818);
	static final Color SPLAT_RED_DARK = new Color(0x741010);
	static final Color SPLAT_GOLD = new Color(0xC88810);
	static final Color SPLAT_GOLD_DARK = new Color(0x7C5408);
	static final Color SPLAT_BLUE = new Color(0x2858B8);
	static final Color SPLAT_BLUE_DARK = new Color(0x183878);

	static final Color DIM_OVERLAY = new Color(0, 0, 0, 150);
	static final Color PANEL_OVERLAY = new Color(0, 0, 0, 205);
	static final Color ARROW_SHAFT = new Color(0xD8C8A0);
	static final Color DART_SHAFT = new Color(0x8A6A3A);
	static final Color DART_TIP = new Color(0xD0D4D8);
	static final Color VALID_FILL = new Color(60, 220, 60, 70);
	static final Color INVALID_FILL = new Color(230, 50, 40, 90);
	static final Color CLOSED_ROUTE = new Color(0, 0, 0, 150);
	static final Color PETRIFIED = new Color(120, 120, 115, 170);
	static final Color BURN_CHIP = new Color(0xFF7020);
	static final Color SLOW_CHIP = new Color(0x70C8F0);
	static final Color ROOT_CHIP = new Color(0x58B030);
	static final Color CURSE_CHIP = new Color(0xB060E0);
	static final Color BIND_FILL = new Color(88, 176, 48, 110);
	static final Color BIND_LINE = new Color(0xB8F080);
	static final Color RANGE_FILL = new Color(255, 255, 255, 28);
	static final Color RANGE_LINE = new Color(255, 255, 255, 130);
	static final Color SELECT_LINE = new Color(0xFFE040);
	static final Color XP_FILL = new Color(0x1F7A2E);
	static final Color WAVE_FILL = new Color(0xC88810);

	private Theme()
	{
	}

	static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	static Font bold()
	{
		return FontManager.getRunescapeBoldFont();
	}

	/** Text with the game's hard one-pixel drop shadow. */
	static void text(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	static void centered(Graphics2D g, String s, int cx, int y, Color c)
	{
		text(g, s, cx - g.getFontMetrics().stringWidth(s) / 2, y, c);
	}

	/** A raised stone slab with a highlight on the top left and shade on the bottom right. */
	static void slab(Graphics2D g, int x, int y, int w, int h, Color face)
	{
		g.setColor(STONE_EDGE);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(face);
		g.fillRect(x + 1, y + 1, w - 2, h - 2);
		g.setColor(face.brighter());
		g.drawLine(x + 1, y + 1, x + w - 2, y + 1);
		g.drawLine(x + 1, y + 1, x + 1, y + h - 2);
		g.setColor(face.darker());
		g.drawLine(x + 1, y + h - 2, x + w - 2, y + h - 2);
		g.drawLine(x + w - 2, y + 2, x + w - 2, y + h - 2);
	}
}
